	bool SliderNVerticalScalar( char const* label, ImGuiDataType data_type, void* ordered_value, int value_count, void* p_min, void* p_max, float cursor_height, bool show_hover_by_region, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		IM_ASSERT( value_count > 1 );

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		const ImGuiID id = window->GetID( label );

		// Convert Lp → Px for all spatial sizes
		float cursorH  = LpToPx( cursor_height );
		float widget_w = ( size.x > 0.0f ) ? LpToPx( size.x ) : LpToPx( 20.0f );
		float widget_h = ( size.y > 0.0f ) ? LpToPx( size.y ) : LpToPx( 160.0f );

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );

		// frame_bb excludes cursorH top and bottom so end-cursors don't clip
		const ImRect frame_bb( window->DC.CursorPos + ImVec2( 0.0f, cursorH ),
		                       window->DC.CursorPos + ImVec2( widget_w, widget_h - cursorH ) );
		const ImRect total_bb( window->DC.CursorPos,
		                       window->DC.CursorPos + ImVec2( widget_w + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ), widget_h ) );

		float fMin = ScalarToFloat( data_type, ( ImU64* )p_min );
		float fMax = ScalarToFloat( data_type, ( ImU64* )p_max );
		float range = fMax - fMin;

		ImVector<ImGuiID> ids;
		ids.resize( value_count );
		ids[ 0 ] = window->GetID( id );
		for ( int k = 1; k < value_count; ++k )
			ids[ k ] = window->GetID( ids[ k - 1 ] );

		// centers[k] = normalized screen-Y of the boundary between regions k-1 and k.
		// Y is inverted: fMin → bottom (y_norm=1), fMax → top (y_norm=0).
		// So centers is descending: centers[0]=1, ..., centers[value_count]=0.
		ImVector<float> centers;
		centers.resize( value_count + 1 );
		centers[ 0 ] = 1.0f;
		for ( int k = 1; k < value_count; ++k )
		{
			float mid = ScalarIndirectToFloat( data_type, ordered_value, k - 1 ) * 0.5f
			          + ScalarIndirectToFloat( data_type, ordered_value, k     ) * 0.5f;
			centers[ k ] = 1.0f - Rescale01( mid, fMin, fMax );
		}
		centers[ value_count ] = 0.0f;

		// drag_bbs: horizontal bands. centers is descending so centers[k] < centers[k-1].
		// Min.y uses centers[k] (smaller value → higher on screen → smaller Y).
		// Max.y uses centers[k-1] (larger Y = lower on screen).
		ImVector<ImRect> drag_bbs;
		drag_bbs.resize( value_count );
		for ( int k = 1; k <= value_count; ++k )
		{
			drag_bbs[ k - 1 ] = ImRect(
				ImVec2( frame_bb.Min.x, ImLerp( frame_bb.Min.y, frame_bb.Max.y, centers[ k     ] ) ),
				ImVec2( frame_bb.Max.x, ImLerp( frame_bb.Min.y, frame_bb.Max.y, centers[ k - 1 ] ) )
			);
		}

		ImGui::ItemSize( total_bb, style.FramePadding.y );

		float frame_h = frame_bb.GetHeight() > 0.0f ? frame_bb.GetHeight() : 1.0f;
		ImRect grab_bb;
		bool value_changed = false;
		bool full_hovered = false;
		bool is_active = false;
		for ( int k = 0; k < value_count; ++k )
		{
			ImRect& bb = drag_bbs[ k ];

			if ( !ImGui::ItemAdd( total_bb, ids[ k ], &bb, 0 ) )
				return false;

			const bool hovered = ImGui::ItemHoverable( bb, ids[ k ], g.LastItemData.ItemFlags );
			full_hovered |= hovered;

			const bool clicked = hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, ids[ k ] );
			const bool make_active = ( clicked || g.NavActivateId == ids[ k ] );
			if ( make_active && clicked )
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, ids[ k ] );

			if ( make_active )
			{
				ImGui::SetActiveID( ids[ k ], window );
				ImGui::SetFocusID( ids[ k ], window );
				ImGui::FocusWindow( window );
				g.ActiveIdUsingNavDirMask |= ( 1 << ImGuiDir_Up ) | ( 1 << ImGuiDir_Down );
			}

			is_active |= ( g.ActiveId == ids[ k ] );
			if ( show_hover_by_region )
			{
				const ImU32 frame_col = ImGui::GetColorU32( g.ActiveId == ids[ k ] ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
				ImGui::RenderNavCursor( bb, ids[ k ] );
				ImGui::RenderFrame( bb.Min, bb.Max, frame_col, true, g.Style.FrameRounding );
			}

			// Local value range for this band.
			// bb.Min.y is top of band → maps to higher value (Y inverted).
			// bb.Max.y is bottom → lower value.
			float v_band_max_f = fMin + ( 1.0f - ( bb.Min.y - frame_bb.Min.y ) / frame_h ) * range;
			float v_band_min_f = fMin + ( 1.0f - ( bb.Max.y - frame_bb.Min.y ) / frame_h ) * range;
			ImU64 v_local_min  = FloatToScalar( data_type, ImMin( v_band_min_f, v_band_max_f ) );
			ImU64 v_local_max  = FloatToScalar( data_type, ImMax( v_band_min_f, v_band_max_f ) );
			ImU64 currentValue = FloatToScalar( data_type, ScalarIndirectToFloat( data_type, ordered_value, k ) );

			bool current_value_changed = ImGui::SliderBehavior( bb, ids[ k ], data_type, &currentValue, &v_local_min, &v_local_max, NULL,
			                                                    ImGuiSliderFlags_NoInput | ImGuiSliderFlags_NoRoundToFormat | ImGuiSliderFlags_Vertical, &grab_bb );
			if ( current_value_changed )
			{
				SetScalarIndirect( data_type, ordered_value, k, &currentValue );
				ImGui::MarkItemEdited( ids[ k ] );
			}
			value_changed |= current_value_changed;
		}

		if ( !show_hover_by_region )
		{
			const ImU32 frame_col = ImGui::GetColorU32( is_active ? ImGuiCol_FrameBgActive : full_hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
			ImGui::RenderNavCursor( frame_bb, id );
			ImGui::RenderFrame( frame_bb.Min, frame_bb.Max, frame_col, true, g.Style.FrameRounding );
		}

		// Vertical signets: tip at frame_bb.Min.x, body extends right. angle=-PI/2 rotates the
		// normal (downward) signet 90° CW so it points right from the left edge.
		ImDrawList* dl = window->DrawList;
		float frame_w = frame_bb.GetWidth();
		for ( int k = 0; k < value_count; ++k )
		{
			float val = ScalarIndirectToFloat( data_type, ordered_value, k );
			float t   = ( range > 0.0f ) ? ImClamp( ( val - fMin ) / range, 0.0f, 1.0f ) : 0.0f;
			float y   = ImLerp( frame_bb.Max.y, frame_bb.Min.y, t );  // Y inverted: t=0 → bottom, t=1 → top
			float align01 = ( k == 0 ) ? 0.0f : ( k == value_count - 1 ) ? 1.0f : 0.5f;
			DrawSignetFilledCursor( dl, ImVec2( frame_bb.Min.x, y ), cursorH, frame_w, 1.0f / 3.0f, align01, -IM_PI * 0.5f, IM_COL32( 255, 0, 0, 255 ) );
		}

		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		return value_changed;
	}

	bool SliderNVerticalFloat( char const* label, float* ordered_value, int value_count, float v_min, float v_max, float cursor_height, bool show_hover_by_region, ImVec2 size )
	{
		return SliderNVerticalScalar( label, ImGuiDataType_Float, ordered_value, value_count, &v_min, &v_max, cursor_height, show_hover_by_region, size );
	}

	bool SliderNVerticalInt( char const* label, int* ordered_value, int value_count, int v_min, int v_max, float cursor_height, bool show_hover_by_region, ImVec2 size )
	{
		return SliderNVerticalScalar( label, ImGuiDataType_S32, ordered_value, value_count, &v_min, &v_max, cursor_height, show_hover_by_region, size );
	}

	// TODO: Add bool flipY
	bool Slider2DScalar( char const* label, ImGuiDataType data_type, void* p_valueX, void* p_valueY, void* p_minX, void* p_maxX, void* p_minY, void* p_maxY )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		IM_ASSERT( ScalarToFloat( data_type, ( ImU64* )p_minX ) < ScalarToFloat( data_type, ( ImU64* )p_maxX ) );
		IM_ASSERT( ScalarToFloat( data_type, ( ImU64* )p_minY ) < ScalarToFloat( data_type, ( ImU64* )p_maxY ) );

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		const ImGuiID id = window->GetID( label );
		ImGuiID idX = window->GetID( id );
		ImGuiID idY = window->GetID( idX );
		const float w = ImGui::CalcItemWidth();

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );

		// Get style colors for cursors
		ImWidgetsStyle& widgetStyle = GetStyle();
		ImVec4 vBlue = widgetStyle.Colors[ StyleColor_Slider2D_CursorX ];
		ImVec4 vOrange = widgetStyle.Colors[ StyleColor_Slider2D_CursorY ];
		ImU32 uBlue = ImGui::GetColorU32( vBlue );
		ImU32 uOrange = ImGui::GetColorU32( vOrange );

		float downScale = 0.75f;
		float dragX_placement = 0.75f;
		float dragY_placement = 0.75f;
		float dragX_thickness = ImTrunc( LpToPx( widgetStyle.Slider2D_DragThickness ) );
		float dragY_thickness = ImTrunc( LpToPx( widgetStyle.Slider2D_DragThickness ) );
		float border_thickness = LpToPx( widgetStyle.Slider2D_BorderThickness );
		float line_thickness = LpToPx( widgetStyle.Slider2D_LineThickness );
		float text_lerp_x = 0.5f;
		float text_lerp_y = 0.5f;
		float cursor_radius = LpToPx( widgetStyle.Slider2D_CursorRadius );
		int cursor_segments = 4;
		float fCursorOff = LpToPx( widgetStyle.Slider2D_CursorOffset );

		// Snap all rects to integer pixel boundaries for crisp borders
		const ImRect frame_bb( ImTrunc( window->DC.CursorPos ), ImTrunc( window->DC.CursorPos + ImVec2( w, w ) ) );
		const ImRect frame_bb_drag( ImTrunc( window->DC.CursorPos ), ImTrunc( window->DC.CursorPos + ImVec2( w * downScale, w * downScale ) ) );
		const ImRect total_bb( frame_bb.Min, frame_bb.Max + ImVec2( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f ) );
		float dragX_y = ImTrunc( ImLerp( frame_bb_drag.Max.y, frame_bb.Max.y, dragX_placement ) );
		float dragY_x = ImTrunc( ImLerp( frame_bb_drag.Max.x, frame_bb.Max.x, dragY_placement ) );
		const ImRect frame_bb_dragX( ImVec2( frame_bb_drag.Min.x, dragX_y ),
									 ImVec2( frame_bb_drag.Max.x, dragX_y + dragX_thickness ) );
		const ImRect frame_bb_dragY( ImVec2( dragY_x, frame_bb_drag.Min.y ),
									 ImVec2( dragY_x + dragY_thickness, frame_bb_drag.Max.y ) );

		float fXLimit = fCursorOff / frame_bb_drag.GetWidth();
		float fYLimit = fCursorOff / frame_bb_drag.GetHeight();

		const ImVec2 curPos = window->DC.CursorPos;

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &frame_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( frame_bb_drag, id, g.LastItemData.ItemFlags );

		bool clicked = hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, id );
		bool make_active = ( clicked || g.NavActivateId == id );
		if ( make_active && clicked )
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );

		if ( make_active )
		{
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			g.ActiveIdUsingNavDirMask |= ( 1 << ImGuiDir_Left ) | ( 1 << ImGuiDir_Right );
		}

		// Draw frame
		ImU32 frame_col = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderNavCursor( frame_bb_drag, id );
		ImGui::RenderFrame( frame_bb_drag.Min, frame_bb_drag.Max, frame_col, true, g.Style.FrameRounding );

		// Slider behavior
		ImRect grab_bbX;
		ImRect grab_bbY;
		bool value_changedX = ImGui::SliderBehavior( frame_bb_drag, id, data_type, p_valueX, p_minX, p_maxX, NULL, ImGuiSliderFlags_NoInput | ImGuiSliderFlags_NoRoundToFormat, &grab_bbX );
		bool value_changedY = ImGui::SliderBehavior( frame_bb_drag, id, data_type, p_valueY, p_minY, p_maxY, NULL, ImGuiSliderFlags_NoInput | ImGuiSliderFlags_NoRoundToFormat | ImGuiSliderFlags_Vertical, &grab_bbY );
		if ( value_changedX || value_changedY )
			ImGui::MarkItemEdited( id );

		if ( !ImGui::ItemAdd( total_bb, idX, &frame_bb_dragX, 0 ) )
			return false;

		hovered = ImGui::ItemHoverable( frame_bb_dragX, idX, g.LastItemData.ItemFlags );

		clicked = hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, idX );
		make_active = ( clicked || g.NavActivateId == idX );
		if ( make_active && clicked )
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, idX );

		if ( make_active )
		{
			ImGui::SetActiveID( idX, window );
			ImGui::SetFocusID( idX, window );
			ImGui::FocusWindow( window );
			g.ActiveIdUsingNavDirMask |= ( 1 << ImGuiDir_Left ) | ( 1 << ImGuiDir_Right );
		}
		frame_col = ImGui::GetColorU32( g.ActiveId == idX ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		bool value_changedXS = ImGui::SliderBehavior( frame_bb_dragX, idX, data_type, p_valueX, p_minX, p_maxX, NULL, ImGuiSliderFlags_NoInput | ImGuiSliderFlags_NoRoundToFormat, &grab_bbX );
		if ( value_changedXS )
			ImGui::MarkItemEdited( idX );

		ImGui::RenderNavCursor( frame_bb_dragX, idX );
		ImGui::RenderFrame( frame_bb_dragX.Min, frame_bb_dragX.Max, frame_col, true, g.Style.FrameRounding );

		if ( !ImGui::ItemAdd( total_bb, idY, &frame_bb_dragX, 0 ) )
			return false;

		hovered = ImGui::ItemHoverable( frame_bb_dragY, idY, g.LastItemData.ItemFlags );

		clicked = hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, idY );
		make_active = ( clicked || g.NavActivateId == idY );
		if ( make_active && clicked )
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, idY );

		if ( make_active )
		{
			ImGui::SetActiveID( idY, window );
			ImGui::SetFocusID( idY, window );
			ImGui::FocusWindow( window );
			g.ActiveIdUsingNavDirMask |= ( 1 << ImGuiDir_Left ) | ( 1 << ImGuiDir_Right );
		}
		frame_col = ImGui::GetColorU32( g.ActiveId == idY ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );

		ImGui::RenderNavCursor( frame_bb_dragY, idY );
		ImGui::RenderFrame( frame_bb_dragY.Min, frame_bb_dragY.Max, frame_col, true, g.Style.FrameRounding );

		bool value_changedYS = ImGui::SliderBehavior( frame_bb_dragY, idY, data_type, p_valueY, p_minY, p_maxY, NULL, ImGuiSliderFlags_NoInput | ImGuiSliderFlags_NoRoundToFormat | ImGuiSliderFlags_Vertical, &grab_bbY );
		if ( value_changedYS )
			ImGui::MarkItemEdited( idY );

		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		ImDrawList* pDrawList = window->DrawList;

		ImU64 s_delta_x = SubScalar( data_type, p_maxX, p_minX );
		ImU64 s_delta_y = SubScalar( data_type, p_maxY, p_minY );
		float fDeltaX = ScalarToFloat( data_type, &s_delta_x );
		float fDeltaY = ScalarToFloat( data_type, &s_delta_y );
		float fScaleX = ( ScalarToFloat( data_type, ( ImU64* )p_valueX ) - ScalarToFloat( data_type, ( ImU64* )p_minX ) ) / fDeltaX;
		float fScaleY = 1.0f - ( ScalarToFloat( data_type, ( ImU64* )p_valueY ) - ScalarToFloat( data_type, ( ImU64* )p_minY ) ) / fDeltaY;

		// For integer types, snap cursor to pixel boundaries for crisp rendering
		// Min/max values touch the frame edges; intermediate values are pixel-rounded
		bool is_integer = ( data_type == ImGuiDataType_S8 || data_type == ImGuiDataType_U8 ||
							data_type == ImGuiDataType_S16 || data_type == ImGuiDataType_U16 ||
							data_type == ImGuiDataType_S32 || data_type == ImGuiDataType_U32 ||
							data_type == ImGuiDataType_S64 || data_type == ImGuiDataType_U64 );
		float drag_w = frame_bb_drag.GetWidth();
		float drag_h = frame_bb_drag.GetHeight();
		ImVec2 vCursorPos( frame_bb_drag.Min.x + drag_w * fScaleX,
						   frame_bb_drag.Min.y + drag_h * fScaleY );
		if ( is_integer )
			vCursorPos = ImVec2( ImTrunc( vCursorPos.x + 0.5f ), ImTrunc( vCursorPos.y + 0.5f ) );

		char const* formatX = ImGui::DataTypeGetInfo( data_type )->PrintFmt;
		char const* formatY = ImGui::DataTypeGetInfo( data_type )->PrintFmt;

		//if ( IsPositiveScalar( data_type, ( ImU64* )p_valueX ) )
		//{
		//	formatX = " " + formatX;
		//}
		//if ( IsPositiveScalar( data_type, ( ImU64* )p_valueY ) )
		//{
		//	formatY = " " + formatY;
		//}

		// Cursor
		pDrawList->AddCircleFilled( vCursorPos, cursor_radius, uBlue, cursor_segments );

		// Vertical Line
		if ( fScaleY > 2.0f * fYLimit )
			pDrawList->AddLine( ImVec2( vCursorPos.x, frame_bb_drag.Min.y + fCursorOff ), ImVec2( vCursorPos.x, vCursorPos.y - fCursorOff ), uOrange, line_thickness );
		if ( fScaleY < 1.0f - 2.0f * fYLimit )
			pDrawList->AddLine( ImVec2( vCursorPos.x, frame_bb_drag.Max.y - fCursorOff ), ImVec2( vCursorPos.x, vCursorPos.y + fCursorOff ), uOrange, line_thickness );

		// Horizontal Line
		if ( fScaleX > 2.0f * fXLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Min.x + fCursorOff, vCursorPos.y ), ImVec2( vCursorPos.x - fCursorOff, vCursorPos.y ), uOrange, line_thickness );
		if ( fScaleX < 1.0f - 2.0f * fYLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Max.x - fCursorOff, vCursorPos.y ), ImVec2( vCursorPos.x + fCursorOff, vCursorPos.y ), uOrange, line_thickness );

		// Borders::Right
		pDrawList->AddCircleFilled( ImVec2( frame_bb_drag.Max.x, vCursorPos.y ), LpToPx( widgetStyle.Slider2D_CornerRadius ), uOrange, 3 );
		// Handle Right::Y
		pDrawList->AddNgonFilled( ImVec2( frame_bb_dragY.GetCenter().x, vCursorPos.y ), dragY_thickness * 0.5f, uOrange, 4 );
		if ( fScaleY > fYLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Max.x, frame_bb_drag.Min.y ), ImVec2( frame_bb_drag.Max.x, vCursorPos.y - fCursorOff ), uBlue, border_thickness );
		if ( fScaleY < 1.0f - fYLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Max.x, frame_bb_drag.Max.y ), ImVec2( frame_bb_drag.Max.x, vCursorPos.y + fCursorOff ), uBlue, border_thickness );
		// Borders::Top
		pDrawList->AddCircleFilled( ImVec2( vCursorPos.x, frame_bb_drag.Min.y ), LpToPx( widgetStyle.Slider2D_CornerRadius ), uOrange, 3 );
		if ( fScaleX > fXLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Min.x, frame_bb_drag.Min.y ), ImVec2( vCursorPos.x - fCursorOff, frame_bb_drag.Min.y ), uBlue, border_thickness );
		if ( fScaleX < 1.0f - fXLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Max.x, frame_bb_drag.Min.y ), ImVec2( vCursorPos.x + fCursorOff, frame_bb_drag.Min.y ), uBlue, border_thickness );
		// Borders::Left
		pDrawList->AddCircleFilled( ImVec2( frame_bb_drag.Min.x, vCursorPos.y ), LpToPx( widgetStyle.Slider2D_CornerRadius ), uOrange, 3 );
		if ( fScaleY > fYLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Min.x, frame_bb_drag.Min.y ), ImVec2( frame_bb_drag.Min.x, vCursorPos.y - fCursorOff ), uBlue, border_thickness );
		if ( fScaleY < 1.0f - fYLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Min.x, frame_bb_drag.Max.y ), ImVec2( frame_bb_drag.Min.x, vCursorPos.y + fCursorOff ), uBlue, border_thickness );
		// Borders::Bottom
		pDrawList->AddCircleFilled( ImVec2( vCursorPos.x, frame_bb_drag.Max.y ), LpToPx( widgetStyle.Slider2D_CornerRadius ), uOrange, 3 );
		// Handle Bottom::X
		pDrawList->AddNgonFilled( ImVec2( vCursorPos.x, frame_bb_dragX.GetCenter().y ), dragX_thickness * 0.5f, uOrange, 4 );
		if ( fScaleX > fXLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Min.x, frame_bb_drag.Max.y ), ImVec2( vCursorPos.x - fCursorOff, frame_bb_drag.Max.y ), uBlue, border_thickness );
		if ( fScaleX < 1.0f - fXLimit )
			pDrawList->AddLine( ImVec2( frame_bb_drag.Max.x, frame_bb_drag.Max.y ), ImVec2( vCursorPos.x + fCursorOff, frame_bb_drag.Max.y ), uBlue, border_thickness );

		// Add Text
		char pBufferX[ 64 ];
		char pBufferY[ 64 ];
		ImGui::DataTypeFormatString( pBufferX, IM_ARRAYSIZE( pBufferX ), data_type, p_valueX, formatX );
		ImGui::DataTypeFormatString( pBufferY, IM_ARRAYSIZE( pBufferY ), data_type, p_valueY, formatY );

		ImU32 const uTextCol = ImGui::ColorConvertFloat4ToU32( ImGui::GetStyle().Colors[ ImGuiCol_Text ] );

		// Note: Text scaling removed - ImGui::SetWindowFontScale() deprecated
		// If smaller text is needed, use ImGui::PushFont() with a pre-scaled font
		ImVec2 const vXSize = ImGui::CalcTextSize( pBufferX );
		ImVec2 const vYSize = ImGui::CalcTextSize( pBufferY );

		pDrawList->AddText(
			ImVec2(
				ImClamp( vCursorPos.x - vXSize.x * 0.5f, frame_bb_drag.Min.x, frame_bb_drag.Min.x + frame_bb_drag.GetWidth() - vXSize.x ),
				ImLerp( frame_bb_drag.Max.y, frame_bb_dragX.Min.y - vXSize.y, text_lerp_x ) ),
			uTextCol,
			pBufferX );
		pDrawList->AddText(
			ImVec2( ImLerp( frame_bb_drag.Max.x, frame_bb_dragY.Min.x - vYSize.x, text_lerp_y ),
					ImClamp( vCursorPos.y - vXSize.y * 0.5f, frame_bb_drag.Min.y, frame_bb_drag.Min.y + frame_bb_drag.GetHeight() - vYSize.y ) ),
			uTextCol,
			pBufferY );

		return value_changedX || value_changedY || value_changedXS || value_changedYS;
	}

	bool Slider2DFloat( char const* pLabel, float* pValueX, float* pValueY, float v_minX, float v_maxX, float v_minY, float v_maxY )
	{
		return Slider2DScalar( pLabel, ImGuiDataType_Float, pValueX, pValueY, &v_minX, &v_maxX, &v_minY, &v_maxY );
	}

	bool Slider2DInt( char const* pLabel, int* pValueX, void* pValueY, int v_minX, int v_maxX, int v_minY, int v_maxY )
	{
		return Slider2DScalar( pLabel, ImGuiDataType_S32, pValueX, pValueY, &v_minX, &v_maxX, &v_minY, &v_maxY );
	}

	bool Slider2DRangeScalar( const char* label, ImGuiDataType data_type,
		void* p_minX, void* p_minY, void* p_maxX, void* p_maxY,
		void* b_minX, void* b_maxX, void* b_minY, void* b_maxY )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		IM_ASSERT( ScalarToFloat( data_type, (ImU64*)b_minX ) < ScalarToFloat( data_type, (ImU64*)b_maxX ) );
		IM_ASSERT( ScalarToFloat( data_type, (ImU64*)b_minY ) < ScalarToFloat( data_type, (ImU64*)b_maxY ) );

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );
		const float w = ImGui::CalcItemWidth();

		// Style sizes
		float handleR         = LpToPx( dwStyle.Slider2DRange_HandleRadius );
		float borderThk       = LpToPx( dwStyle.Slider2D_BorderThickness );
		float lineThk         = LpToPx( dwStyle.Slider2D_LineThickness );
		float cursorOff       = LpToPx( dwStyle.Slider2D_CursorOffset );
		float cornerR         = LpToPx( dwStyle.Slider2D_CornerRadius );
		float dragX_thickness = ImTrunc( LpToPx( dwStyle.Slider2D_DragThickness ) );
		float dragY_thickness = dragX_thickness;

		// Layout: 75% main drag area + bottom X strip + right Y strip (matches Slider2DFloat/Int)
		constexpr float downScale = 0.75f;
		const ImVec2 cursor = window->DC.CursorPos;
		const ImRect frame_bb( ImTrunc( cursor ), ImTrunc( cursor + ImVec2( w, w ) ) );
		const ImRect frame_bb_drag( ImTrunc( cursor ), ImTrunc( cursor + ImVec2( w * downScale, w * downScale ) ) );
		float dragX_y = ImTrunc( ImLerp( frame_bb_drag.Max.y, frame_bb.Max.y, 0.75f ) );
		float dragY_x = ImTrunc( ImLerp( frame_bb_drag.Max.x, frame_bb.Max.x, 0.75f ) );
		const ImRect frame_bb_dragX( ImVec2( frame_bb_drag.Min.x, dragX_y ), ImVec2( frame_bb_drag.Max.x, dragX_y + dragX_thickness ) );
		const ImRect frame_bb_dragY( ImVec2( dragY_x, frame_bb_drag.Min.y ), ImVec2( dragY_x + dragY_thickness, frame_bb_drag.Max.y ) );

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );
		const ImRect total_bb( frame_bb.Min, frame_bb.Max + ImVec2( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &frame_bb, 0 ) )
			return false;

		float bMinXF = ScalarToFloat( data_type, (ImU64*)b_minX );
		float bMaxXF = ScalarToFloat( data_type, (ImU64*)b_maxX );
		float bMinYF = ScalarToFloat( data_type, (ImU64*)b_minY );
		float bMaxYF = ScalarToFloat( data_type, (ImU64*)b_maxY );
		float denX   = bMaxXF - bMinXF;
		float denY   = bMaxYF - bMinYF;
		float drag_w = frame_bb_drag.GetWidth();
		float drag_h = frame_bb_drag.GetHeight();

		auto NormX = [&]( void* p ) -> float {
			return ( denX > 0.0f ) ? ImClamp( ( ScalarToFloat( data_type, (ImU64*)p ) - bMinXF ) / denX, 0.0f, 1.0f ) : 0.0f;
		};
		auto NormY = [&]( void* p ) -> float {
			return ( denY > 0.0f ) ? ImClamp( ( ScalarToFloat( data_type, (ImU64*)p ) - bMinYF ) / denY, 0.0f, 1.0f ) : 0.0f;
		};

		ImGuiStorage* storage = window->DC.StateStorage;
		ImGuiID activeKey  = id ^ 0xBE4F1234u;
		ImGuiID initMxKey  = id ^ 0xBE4F1235u;
		ImGuiID initMyKey  = id ^ 0xBE4F1236u;
		ImGuiID initMnXKey = id ^ 0xBE4F1237u;
		ImGuiID initMnYKey = id ^ 0xBE4F1238u;
		ImGuiID initMxXKey = id ^ 0xBE4F1239u;
		ImGuiID initMxYKey = id ^ 0xBE4F123Au;

		// Interaction on frame_bb_drag only (not the full frame_bb)
		bool hovered = ImGui::ItemHoverable( frame_bb_drag, id, g.LastItemData.ItemFlags );
		bool value_changed = false;

		auto MouseTX = [&]() -> float { return ImClamp( ( g.IO.MousePos.x - frame_bb_drag.Min.x ) / drag_w, 0.0f, 1.0f ); };
		auto MouseTY = [&]() -> float { return ImClamp( ( g.IO.MousePos.y - frame_bb_drag.Min.y ) / drag_h, 0.0f, 1.0f ); };

		if ( hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, id ) )
		{
			float tx = MouseTX(), ty = MouseTY();
			float tnMinX = NormX( p_minX ), tnMinY = NormY( p_minY );
			float tnMaxX = NormX( p_maxX ), tnMaxY = NormY( p_maxY );
			// Y not inverted: min value = top-left, max value = bottom-right
			float sMinY_n = tnMinY;
			float sMaxY_n = tnMaxY;
			float rectY0  = ImMin( sMinY_n, sMaxY_n );
			float rectY1  = ImMax( sMinY_n, sMaxY_n );
			float rectX0  = ImMin( tnMinX, tnMaxX );
			float rectX1  = ImMax( tnMinX, tnMaxX );

			int active;
			if ( tx >= rectX0 && tx <= rectX1 && ty >= rectY0 && ty <= rectY1 )
			{
				active = 3;
				storage->SetFloat( initMxKey,  tx );
				storage->SetFloat( initMyKey,  ty );
				storage->SetFloat( initMnXKey, tnMinX );
				storage->SetFloat( initMnYKey, tnMinY );
				storage->SetFloat( initMxXKey, tnMaxX );
				storage->SetFloat( initMxYKey, tnMaxY );
			}
			else
			{
				float dMinSq = ( tx - tnMinX ) * ( tx - tnMinX ) + ( ty - sMinY_n ) * ( ty - sMinY_n );
				float dMaxSq = ( tx - tnMaxX ) * ( tx - tnMaxX ) + ( ty - sMaxY_n ) * ( ty - sMaxY_n );
				active = ( dMaxSq < dMinSq ) ? 2 : 1;
			}

			storage->SetInt( activeKey, active );
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}

		if ( g.ActiveId == id )
		{
			if ( g.IO.MouseDown[ 0 ] )
			{
				int   active = storage->GetInt( activeKey, 0 );
				float tx     = MouseTX(), ty = MouseTY();
				float newX   = bMinXF + tx * denX;
				float newY   = bMinYF + ty * denY;

				if ( active == 1 )
				{
					newX = ImClamp( newX, bMinXF, ScalarToFloat( data_type, (ImU64*)p_maxX ) );
					newY = ImClamp( newY, bMinYF, ScalarToFloat( data_type, (ImU64*)p_maxY ) );
					WriteFloatToScalar( data_type, p_minX, newX );
					WriteFloatToScalar( data_type, p_minY, newY );
					value_changed = true;
				}
				else if ( active == 2 )
				{
					newX = ImClamp( newX, ScalarToFloat( data_type, (ImU64*)p_minX ), bMaxXF );
					newY = ImClamp( newY, ScalarToFloat( data_type, (ImU64*)p_minY ), bMaxYF );
					WriteFloatToScalar( data_type, p_maxX, newX );
					WriteFloatToScalar( data_type, p_maxY, newY );
					value_changed = true;
				}
				else if ( active == 3 )
				{
					float initMx  = storage->GetFloat( initMxKey,  0.5f );
					float initMy  = storage->GetFloat( initMyKey,  0.5f );
					float initMnX = storage->GetFloat( initMnXKey, 0.0f );
					float initMnY = storage->GetFloat( initMnYKey, 0.0f );
					float initMxX = storage->GetFloat( initMxXKey, 1.0f );
					float initMxY = storage->GetFloat( initMxYKey, 1.0f );
					float dtx     = ( tx - initMx );
					float dty     = ( ty - initMy );
					float rW      = initMxX - initMnX;
					float rH      = initMxY - initMnY;
					float newMnX  = ImClamp( initMnX + dtx, 0.0f, 1.0f - rW );
					float newMnY  = ImClamp( initMnY + dty, 0.0f, 1.0f - rH );
					WriteFloatToScalar( data_type, p_minX, bMinXF + newMnX * denX );
					WriteFloatToScalar( data_type, p_minY, bMinYF + newMnY * denY );
					WriteFloatToScalar( data_type, p_maxX, bMinXF + ( newMnX + rW ) * denX );
					WriteFloatToScalar( data_type, p_maxY, bMinYF + ( newMnY + rH ) * denY );
					value_changed = true;
				}

				if ( value_changed )
					ImGui::MarkItemEdited( id );
			}
			else
			{
				ImGui::ClearActiveID();
			}
		}

		// Main drag area frame
		ImU32 frameCol = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderNavCursor( frame_bb_drag, id );
		ImGui::RenderFrame( frame_bb_drag.Min, frame_bb_drag.Max, frameCol, true, style.FrameRounding );

		// X strip — SliderN (horizontal): two handles for minX and maxX
		// Y strip — SliderNVertical: two handles for minY and maxY
		// PushID(id) scopes sub-widget IDs under the parent so two Slider2DRange widgets
		// on the same window don't collide. Cursor-pos save/restore keeps layout intact.
		ImGui::PushID( (int)id );
		{
			ImVec2 savedCursorPos    = window->DC.CursorPos;
			ImVec2 savedCursorMaxPos = window->DC.CursorMaxPos;

			int   elem_sz       = (int)ImGui::DataTypeGetInfo( data_type )->Size;
			char  xBuf[16], yBuf[16], tmpBuf[8];
			float cursor_w      = dragX_thickness * 0.5f;  // already px
			float cursor_h      = dragY_thickness * 0.5f;  // already px
			float cursor_wLp    = PxToLp( cursor_w );

			// SliderNScalar reserves cursor_w on each side inside its item width.
			// SliderNVerticalScalar reserves cursor_h at top and bottom inside its height.
			// Expand the position/size by those margins so the inner track aligns exactly
			// with frame_bb_drag.
			memcpy( xBuf,           p_minX, elem_sz );
			memcpy( xBuf + elem_sz, p_maxX, elem_sz );
			window->DC.CursorPos = ImVec2( frame_bb_dragX.Min.x - cursor_w, frame_bb_dragX.Min.y );
			ImGui::SetNextItemWidth( frame_bb_dragX.GetWidth() + 2.0f * cursor_w );
			if ( SliderNScalar( "##x", data_type, xBuf, 2, b_minX, b_maxX, cursor_wLp, false ) )
			{
				if ( ScalarToFloat( data_type, (ImU64*)xBuf ) > ScalarToFloat( data_type, (ImU64*)( xBuf + elem_sz ) ) )
				{
					memcpy( tmpBuf, xBuf, elem_sz );
					memcpy( xBuf, xBuf + elem_sz, elem_sz );
					memcpy( xBuf + elem_sz, tmpBuf, elem_sz );
				}
				memcpy( p_minX, xBuf,           elem_sz );
				memcpy( p_maxX, xBuf + elem_sz, elem_sz );
				value_changed = true;
			}

			memcpy( yBuf,           p_minY, elem_sz );
			memcpy( yBuf + elem_sz, p_maxY, elem_sz );
			window->DC.CursorPos = ImVec2( frame_bb_dragY.Min.x, frame_bb_dragY.Min.y - cursor_h );
			ImVec2 stripYSizeLp  = PxToLp( ImVec2( frame_bb_dragY.GetWidth(), frame_bb_dragY.GetHeight() + 2.0f * cursor_h ) );
			float  cursorHLp     = PxToLp( cursor_h );
			if ( SliderNVerticalScalar( "##y", data_type, yBuf, 2, b_minY, b_maxY, cursorHLp, false, stripYSizeLp ) )
			{
				if ( ScalarToFloat( data_type, (ImU64*)yBuf ) > ScalarToFloat( data_type, (ImU64*)( yBuf + elem_sz ) ) )
				{
					memcpy( tmpBuf, yBuf, elem_sz );
					memcpy( yBuf, yBuf + elem_sz, elem_sz );
					memcpy( yBuf + elem_sz, tmpBuf, elem_sz );
				}
				memcpy( p_minY, yBuf,           elem_sz );
				memcpy( p_maxY, yBuf + elem_sz, elem_sz );
				value_changed = true;
			}

			window->DC.CursorPos    = savedCursorPos;
			window->DC.CursorMaxPos = savedCursorMaxPos;
		}
		ImGui::PopID();

		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		ImDrawList* dl = window->DrawList;

		ImU32 uBlue   = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DRange_MinHandle ] );
		ImU32 uOrange = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DRange_MaxHandle ] );
		ImU32 uFrame  = ImGui::GetColorU32( ImGuiCol_FrameBg );

		// Normalized handle positions → screen coords inside frame_bb_drag (Y not inverted: min at top)
		float tMinX = NormX( p_minX ), tMinY = NormY( p_minY );
		float tMaxX = NormX( p_maxX ), tMaxY = NormY( p_maxY );
		float sMinX = frame_bb_drag.Min.x + tMinX * drag_w;
		float sMinY = frame_bb_drag.Min.y + tMinY * drag_h;
		float sMaxX = frame_bb_drag.Min.x + tMaxX * drag_w;
		float sMaxY = frame_bb_drag.Min.y + tMaxY * drag_h;

		// Selection rect (sorted)
		float selLeft   = ImMin( sMinX, sMaxX );
		float selRight  = ImMax( sMinX, sMaxX );
		float selTop    = ImMin( sMinY, sMaxY );
		float selBottom = ImMax( sMinY, sMaxY );

		// Drag area boundaries
		float bbLeft   = frame_bb_drag.Min.x;
		float bbRight  = frame_bb_drag.Max.x;
		float bbTop    = frame_bb_drag.Min.y;
		float bbBottom = frame_bb_drag.Max.y;
		float gap      = cursorOff;

		// Selection fill
		dl->AddRectFilled( ImVec2( selLeft, selTop ), ImVec2( selRight, selBottom ),
		                   ImGui::GetColorU32( ImGuiCol_FrameBgActive ) );

		// Orange lines — all unconditional; scissor rect handles out-of-bounds lines.
		// TOP edge — has blue dots: 3 segments with gaps at selLeft/selRight
		dl->AddLine( ImVec2( bbLeft,         bbTop ), ImVec2( selLeft - gap,  bbTop ), uOrange, lineThk );
		dl->AddLine( ImVec2( selLeft + gap,  bbTop ), ImVec2( selRight - gap, bbTop ), uOrange, lineThk );
		dl->AddLine( ImVec2( selRight + gap, bbTop ), ImVec2( bbRight,        bbTop ), uOrange, lineThk );
		// BOTTOM edge — has blue bar: 2 segments stopping exactly at selLeft/selRight
		dl->AddLine( ImVec2( bbLeft,   bbBottom ), ImVec2( selLeft,  bbBottom ), uOrange, lineThk );
		dl->AddLine( ImVec2( selRight, bbBottom ), ImVec2( bbRight,  bbBottom ), uOrange, lineThk );
		// LEFT edge — has blue dots: 3 segments with gaps at selTop/selBottom
		dl->AddLine( ImVec2( bbLeft, bbTop          ), ImVec2( bbLeft, selTop - gap     ), uOrange, lineThk );
		dl->AddLine( ImVec2( bbLeft, selTop + gap   ), ImVec2( bbLeft, selBottom - gap  ), uOrange, lineThk );
		dl->AddLine( ImVec2( bbLeft, selBottom + gap ), ImVec2( bbLeft, bbBottom        ), uOrange, lineThk );
		// RIGHT edge — has blue bar: 2 segments stopping exactly at selTop/selBottom
		dl->AddLine( ImVec2( bbRight, bbTop     ), ImVec2( bbRight, selTop    ), uOrange, lineThk );
		dl->AddLine( ImVec2( bbRight, selBottom ), ImVec2( bbRight, bbBottom  ), uOrange, lineThk );

		// Blue dots on TOP (at selLeft/selRight) and LEFT (at selTop/selBottom)
		dl->AddCircleFilled( ImVec2( selLeft,  bbTop     ), cornerR, uBlue, 3 );
		dl->AddCircleFilled( ImVec2( selRight, bbTop     ), cornerR, uBlue, 3 );
		dl->AddCircleFilled( ImVec2( bbLeft,   selTop    ), cornerR, uBlue, 3 );
		dl->AddCircleFilled( ImVec2( bbLeft,   selBottom ), cornerR, uBlue, 3 );

		// Blue ticks + bars on BOTTOM (X) and RIGHT (Y)
		float barHalf = gap * 0.5f;
		float selW    = selRight - selLeft;
		float selH    = selBottom - selTop;
		// Bottom: ticks crossing the edge, bar spanning middle 50% of X extent
		dl->AddLine( ImVec2( selLeft,  bbBottom - gap ), ImVec2( selLeft,  bbBottom + gap ), uBlue, borderThk );
		dl->AddLine( ImVec2( selRight, bbBottom - gap ), ImVec2( selRight, bbBottom + gap ), uBlue, borderThk );
		dl->AddRectFilled( ImVec2( selLeft  + 0.25f * selW, bbBottom - barHalf ),
		                   ImVec2( selRight - 0.25f * selW, bbBottom + barHalf ), uBlue );
		// Right: ticks crossing the edge, bar spanning middle 50% of Y extent
		dl->AddLine( ImVec2( bbRight - gap, selTop    ), ImVec2( bbRight + gap, selTop    ), uBlue, borderThk );
		dl->AddLine( ImVec2( bbRight - gap, selBottom ), ImVec2( bbRight + gap, selBottom ), uBlue, borderThk );
		dl->AddRectFilled( ImVec2( bbRight - barHalf, selTop    + 0.25f * selH ),
		                   ImVec2( bbRight + barHalf, selBottom - 0.25f * selH ), uBlue );

		// Orange L-shapes pointing inward at corner handles (when selection is large enough)
		if ( selW > gap * 2.0f && selH > gap * 2.0f )
		{
			// sMinX/sMinY = top-left corner
			dl->AddLine( ImVec2( sMinX, sMinY ), ImVec2( sMinX + gap, sMinY ), uOrange, lineThk );
			dl->AddLine( ImVec2( sMinX, sMinY ), ImVec2( sMinX, sMinY + gap ), uOrange, lineThk );
			// sMaxX/sMaxY = bottom-right corner
			dl->AddLine( ImVec2( sMaxX, sMaxY ), ImVec2( sMaxX - gap, sMaxY ), uOrange, lineThk );
			dl->AddLine( ImVec2( sMaxX, sMaxY ), ImVec2( sMaxX, sMaxY - gap ), uOrange, lineThk );
		}

		// Body drag cross at selection center
		ImVec2 selCenter( ( selLeft + selRight ) * 0.5f, ( selTop + selBottom ) * 0.5f );
		dl->AddLine( selCenter - ImVec2( gap, 0.0f ), selCenter + ImVec2( gap, 0.0f ), uFrame, 1.0f );
		dl->AddLine( selCenter - ImVec2( 0.0f, gap ), selCenter + ImVec2( 0.0f, gap ), uFrame, 1.0f );

		// Diamond handles at both corner positions
		int   activeHandle = ( g.ActiveId == id ) ? storage->GetInt( activeKey, 0 ) : 0;
		float activeBoost  = LpToPx( 2.0f );
		dl->AddNgonFilled( ImVec2( sMinX, sMinY ), handleR + ( activeHandle == 1 ? activeBoost : 0.0f ), uBlue, 4 );
		dl->AddNgonFilled( ImVec2( sMaxX, sMaxY ), handleR + ( activeHandle == 2 ? activeBoost : 0.0f ), uBlue, 4 );

		// Value text: X values in gap below drag area, Y values in gap right of drag area
		const char* fmt = ImGui::DataTypeGetInfo( data_type )->PrintFmt;
		char bufMnX[32], bufMnY[32], bufMxX[32], bufMxY[32];
		ImGui::DataTypeFormatString( bufMnX, IM_ARRAYSIZE( bufMnX ), data_type, p_minX, fmt );
		ImGui::DataTypeFormatString( bufMnY, IM_ARRAYSIZE( bufMnY ), data_type, p_minY, fmt );
		ImGui::DataTypeFormatString( bufMxX, IM_ARRAYSIZE( bufMxX ), data_type, p_maxX, fmt );
		ImGui::DataTypeFormatString( bufMxY, IM_ARRAYSIZE( bufMxY ), data_type, p_maxY, fmt );
		ImU32  textCol = ImGui::GetColorU32( style.Colors[ ImGuiCol_Text ] );
		ImVec2 mnXSz   = ImGui::CalcTextSize( bufMnX );
		ImVec2 mxXSz   = ImGui::CalcTextSize( bufMxX );
		ImVec2 mnYSz   = ImGui::CalcTextSize( bufMnY );
		ImVec2 mxYSz   = ImGui::CalcTextSize( bufMxY );
		float  textY   = ImLerp( bbBottom, frame_bb_dragX.Min.y - mnXSz.y, 0.5f );
		float  textX   = ImLerp( bbRight, frame_bb_dragY.Min.x - mnYSz.x, 0.5f );
		dl->AddText( ImVec2( ImClamp( selLeft  - mnXSz.x * 0.5f, bbLeft, bbRight - mnXSz.x ), textY ), textCol, bufMnX );
		dl->AddText( ImVec2( ImClamp( selRight - mxXSz.x * 0.5f, bbLeft, bbRight - mxXSz.x ), textY ), textCol, bufMxX );
		dl->AddText( ImVec2( textX, ImClamp( selTop    - mnYSz.y * 0.5f, bbTop, bbBottom - mnYSz.y ) ), textCol, bufMnY );
		dl->AddText( ImVec2( textX, ImClamp( selBottom - mxYSz.y * 0.5f, bbTop, bbBottom - mxYSz.y ) ), textCol, bufMxY );

		return value_changed;
	}

	bool Slider2DRangeFloat( const char* label, float* pMinX, float* pMinY, float* pMaxX, float* pMaxY,
		float bMinX, float bMaxX, float bMinY, float bMaxY )
	{
		return Slider2DRangeScalar( label, ImGuiDataType_Float, pMinX, pMinY, pMaxX, pMaxY, &bMinX, &bMaxX, &bMinY, &bMaxY );
	}

	bool Slider2DRangeInt( const char* label, int* pMinX, int* pMinY, int* pMaxX, int* pMaxY,
		int bMinX, int bMaxX, int bMinY, int bMaxY )
	{
		return Slider2DRangeScalar( label, ImGuiDataType_S32, pMinX, pMinY, pMaxX, pMaxY, &bMinX, &bMaxX, &bMinY, &bMaxY );
	}

	bool Slider2DDiscScalar( const char* label, ImGuiDataType data_type,
		void* p_valueX, void* p_valueY, void* p_min, void* p_max )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		IM_ASSERT( ScalarToFloat( data_type, (ImU64*)p_min ) < ScalarToFloat( data_type, (ImU64*)p_max ) );

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );
		const float w = ImGui::CalcItemWidth();

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );
		const ImRect frame_bb( ImTrunc( window->DC.CursorPos ), ImTrunc( window->DC.CursorPos + ImVec2( w, w ) ) );
		const ImRect total_bb( frame_bb.Min, frame_bb.Max + ImVec2( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f, 0.0f ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &frame_bb, 0 ) )
			return false;

		float vMinF    = ScalarToFloat( data_type, (ImU64*)p_min );
		float vMaxF    = ScalarToFloat( data_type, (ImU64*)p_max );
		float center_v = ( vMinF + vMaxF ) * 0.5f;
		float radius_v = ( vMaxF - vMinF ) * 0.5f;

		bool hovered = ImGui::ItemHoverable( frame_bb, id, g.LastItemData.ItemFlags );
		bool clicked = hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, id );
		bool make_active = ( clicked || g.NavActivateId == id );
		if ( make_active && clicked )
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		if ( make_active )
		{
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
		}

		ImVec2 center = frame_bb.GetCenter();
		float disc_r = frame_bb.GetWidth() * 0.5f - LpToPx( 2.0f );

		bool value_changed = false;
		if ( g.ActiveId == id )
		{
			if ( g.IO.MouseDown[ 0 ] )
			{
				float mx = g.IO.MousePos.x - center.x;
				float my = g.IO.MousePos.y - center.y;
				float nx = ( disc_r > 0.0f ) ? mx / disc_r : 0.0f;
				float ny = ( disc_r > 0.0f ) ? -my / disc_r : 0.0f;  // flip Y: up = positive
				float len = ImSqrt( nx * nx + ny * ny );
				if ( len > 1.0f ) { nx /= len; ny /= len; }
				float newX = center_v + nx * radius_v;
				float newY = center_v + ny * radius_v;
				float curX = ScalarToFloat( data_type, (ImU64*)p_valueX );
				float curY = ScalarToFloat( data_type, (ImU64*)p_valueY );
				if ( newX != curX || newY != curY )
				{
					WriteFloatToScalar( data_type, p_valueX, newX );
					WriteFloatToScalar( data_type, p_valueY, newY );
					ImGui::MarkItemEdited( id );
					value_changed = true;
				}
			}
			else
			{
				ImGui::ClearActiveID();
			}
		}

		// Disc frame: no outer rectangle — the disc itself is the frame. Use standard FrameBg interaction colors.
		ImU32 frameCol = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderNavCursor( frame_bb, id );

		ImDrawList* dl = window->DrawList;

		// Disc background: if user set an explicit alpha, use that color; otherwise use standard FrameBg (responsive to hover/active).
		ImVec4 bgCol4 = dwStyle.Colors[ StyleColor_Slider2DDisc_Background ];
		ImU32 discFill = ( bgCol4.w > 0.001f ) ? ImGui::GetColorU32( bgCol4 ) : frameCol;
		dl->AddCircleFilled( center, disc_r, discFill, 64 );

		// Outer ring — brighter when hovered or active
		float ringThk = LpToPx( dwStyle.Slider2DDisc_RingThickness );
		ImU32 ringCol;
		if ( g.ActiveId == id )
			ringCol = ImGui::GetColorU32( ImGuiCol_SliderGrabActive );
		else if ( hovered )
			{ ImVec4 rc = dwStyle.Colors[ StyleColor_Slider2DDisc_Ring ]; rc.w = ImMin( rc.w * 1.5f, 1.0f ); ringCol = ImGui::GetColorU32( rc ); }
		else
			ringCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DDisc_Ring ] );
		dl->AddCircle( center, disc_r, ringCol, 64, ringThk );

		// Grid: crosshair + concentric rings
		ImU32 gridCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DDisc_Grid ] );
		dl->AddLine( ImVec2( center.x - disc_r, center.y ), ImVec2( center.x + disc_r, center.y ), gridCol, 1.0f );
		dl->AddLine( ImVec2( center.x, center.y - disc_r ), ImVec2( center.x, center.y + disc_r ), gridCol, 1.0f );
		int nRings = dwStyle.Slider2DDisc_GridRings;
		for ( int ri = 1; ri <= nRings; ++ri )
			dl->AddCircle( center, disc_r * (float)ri / (float)( nRings + 1 ), gridCol, 48, 1.0f );

		// Handle screen position (Y inverted: up = positive Y value)
		float vXF = ScalarToFloat( data_type, (ImU64*)p_valueX );
		float vYF = ScalarToFloat( data_type, (ImU64*)p_valueY );
		float nx  = ( radius_v > 0.0f ) ? ImClamp( ( vXF - center_v ) / radius_v, -1.0f, 1.0f ) : 0.0f;
		float ny  = ( radius_v > 0.0f ) ? ImClamp( ( vYF - center_v ) / radius_v, -1.0f, 1.0f ) : 0.0f;
		float len = ImSqrt( nx * nx + ny * ny );
		if ( len > 1.0f ) { nx /= len; ny /= len; }
		ImVec2 handlePos( center.x + nx * disc_r, center.y - ny * disc_r );

		// Stick arm from center to handle when active
		if ( g.ActiveId == id )
			dl->AddLine( center, handlePos, gridCol, 1.0f );

		// CurveEditor-style handle: filled circle + outline (consistent with ToneCurve/CurveEditor key)
		float handleR = LpToPx( dwStyle.Slider2DDisc_CursorRadius );
		if ( hovered || g.ActiveId == id )
			handleR += LpToPx( 1.5f );
		ImU32 cursorFill    = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DDisc_Cursor ] );
		ImU32 cursorOutline = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Slider2DDisc_CursorOutline ] );
		float outlineThk    = LpToPx( dwStyle.Slider2DDisc_CursorOutlineThickness );
		dl->AddCircleFilled( handlePos, handleR, cursorFill );
		dl->AddCircle( handlePos, handleR, cursorOutline, 0, outlineThk );

		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		// Value text
		const char* fmt = ImGui::DataTypeGetInfo( data_type )->PrintFmt;
		char bufX[32], bufY[32];
		ImGui::DataTypeFormatString( bufX, IM_ARRAYSIZE( bufX ), data_type, p_valueX, fmt );
		ImGui::DataTypeFormatString( bufY, IM_ARRAYSIZE( bufY ), data_type, p_valueY, fmt );
		char tbuf[64];
		snprintf( tbuf, sizeof(tbuf), "(%s, %s)", bufX, bufY );
		ImU32 textCol = ImGui::GetColorU32( style.Colors[ ImGuiCol_Text ] );
		float lineH = ImGui::GetTextLineHeight();
		dl->AddText( ImVec2( frame_bb.Min.x + 4.0f, frame_bb.Max.y - lineH - 1.0f ), textCol, tbuf );

		return value_changed;
	}

	bool Slider2DDiscFloat( const char* label, float* pValueX, float* pValueY, float v_min, float v_max )
	{
		return Slider2DDiscScalar( label, ImGuiDataType_Float, pValueX, pValueY, &v_min, &v_max );
	}

	bool Slider2DDiscInt( const char* label, int* pValueX, int* pValueY, int v_min, int v_max )
	{
		return Slider2DDiscScalar( label, ImGuiDataType_S32, pValueX, pValueY, &v_min, &v_max );
	}

	//////////////////////////////////////////////////////////////////////////
	// Gradient Editor
	//////////////////////////////////////////////////////////////////////////

	static void ImGradientInterpGetFunctions( ImWidgetsGradientInterp interp, pfSpace2sRGB* out_toRGB, pfsRGB2Space* out_fromRGB )
	{
		switch ( interp )
		{
		case ImWidgetsGradientInterp_LinearSRGB:
			*out_toRGB  = &ColorConvertLineartoRGB;
			*out_fromRGB = &ColorConvertRGBtoLinear;
			break;
		case ImWidgetsGradientInterp_OkLab:
			*out_toRGB  = &ColorConvertOKLABtoRGB;
			*out_fromRGB = &ColorConvertRGBtoOKLAB;
			break;
		case ImWidgetsGradientInterp_OkLCH:
			*out_toRGB  = &ColorConvertOKLCHtosRGB;
			*out_fromRGB = &ColorConvertsRGBtoOKLCH;
			break;
		case ImWidgetsGradientInterp_HSV:
			*out_toRGB  = &ColorConvertHSVtoRGB;
			*out_fromRGB = &ColorConvertRGBtoHSV;
			break;
		default: // sRGB
			*out_toRGB  = &ColorConvertsRGBtosRGB;
			*out_fromRGB = &ColorConvertsRGBtosRGB;
			break;
		}
	}

	static bool ImGradientInterpHasHue( ImWidgetsGradientInterp interp )
	{
		return interp == ImWidgetsGradientInterp_OkLCH || interp == ImWidgetsGradientInterp_HSV;
	}

	// Hue component index in the converted space (2 for OkLCH h, 0 for HSV h)
	static int ImGradientInterpHueIdx( ImWidgetsGradientInterp interp )
	{
		if ( interp == ImWidgetsGradientInterp_HSV )
			return 0;
		return 2; // OkLCH: L, C, H
	}

	ImVec4 GradientSample( ImGradientData const& gradient, float t )
	{
		if ( gradient.Stops.Size == 0 )
			return ImVec4( 1.0f, 1.0f, 1.0f, 1.0f );
		if ( gradient.Stops.Size == 1 )
			return gradient.Stops[ 0 ].Color;

		t = ImClamp( t, 0.0f, 1.0f );

		// Find surrounding stops
		if ( t <= gradient.Stops[ 0 ].Position )
			return gradient.Stops[ 0 ].Color;
		if ( t >= gradient.Stops[ gradient.Stops.Size - 1 ].Position )
			return gradient.Stops[ gradient.Stops.Size - 1 ].Color;

		int rightIdx = 0;
		for ( int i = 0; i < gradient.Stops.Size; ++i )
		{
			if ( gradient.Stops[ i ].Position >= t )
			{
				rightIdx = i;
				break;
			}
		}
		int leftIdx = rightIdx - 1;
		if ( leftIdx < 0 )
			leftIdx = 0;

		float segLen = gradient.Stops[ rightIdx ].Position - gradient.Stops[ leftIdx ].Position;
		float f = ( segLen > 1e-6f ) ? ( t - gradient.Stops[ leftIdx ].Position ) / segLen : 0.0f;

		ImVec4 const& colL = gradient.Stops[ leftIdx ].Color;
		ImVec4 const& colR = gradient.Stops[ rightIdx ].Color;

		// Get conversion functions
		pfSpace2sRGB toRGB = NULL;
		pfsRGB2Space fromRGB = NULL;
		ImGradientInterpGetFunctions( gradient.Interpolation, &toRGB, &fromRGB );

		// Convert to interpolation space
		float lComp[ 3 ], rComp[ 3 ];
		fromRGB( lComp[ 0 ], lComp[ 1 ], lComp[ 2 ], colL.x, colL.y, colL.z );
		fromRGB( rComp[ 0 ], rComp[ 1 ], rComp[ 2 ], colR.x, colR.y, colR.z );

		// Interpolate
		float result[ 3 ];
		if ( ImGradientInterpHasHue( gradient.Interpolation ) )
		{
			int hIdx = ImGradientInterpHueIdx( gradient.Interpolation );
			// Shortest-arc hue interpolation
			float h0 = lComp[ hIdx ];
			float h1 = rComp[ hIdx ];
			float delta = h1 - h0;
			if ( delta > 0.5f ) delta -= 1.0f;
			if ( delta < -0.5f ) delta += 1.0f;
			float hResult = h0 + delta * f;
			if ( hResult < 0.0f ) hResult += 1.0f;
			if ( hResult > 1.0f ) hResult -= 1.0f;

			for ( int c = 0; c < 3; ++c )
			{
				if ( c == hIdx )
					result[ c ] = hResult;
				else
					result[ c ] = ImLerp( lComp[ c ], rComp[ c ], f );
			}
		}
		else
		{
			for ( int c = 0; c < 3; ++c )
				result[ c ] = ImLerp( lComp[ c ], rComp[ c ], f );
		}

		// Convert back to sRGB
		ImVec4 out;
		toRGB( out.x, out.y, out.z, result[ 0 ], result[ 1 ], result[ 2 ] );
		out.x = ImClamp( out.x, 0.0f, 1.0f );
		out.y = ImClamp( out.y, 0.0f, 1.0f );
		out.z = ImClamp( out.z, 0.0f, 1.0f );
		out.w = ImLerp( colL.w, colR.w, f ); // Alpha always linear

		// Override alpha from separate alpha track when split
		if ( gradient.SplitAlpha && gradient.AlphaStops.Size >= 2 )
			out.w = GradientAlphaSample( gradient, t );

		return out;
	}

	float GradientAlphaSample( ImGradientData const& gradient, float t )
	{
		if ( gradient.AlphaStops.Size == 0 )
			return 1.0f;
		if ( gradient.AlphaStops.Size == 1 )
			return gradient.AlphaStops[ 0 ].Alpha;

		t = ImClamp( t, 0.0f, 1.0f );

		if ( t <= gradient.AlphaStops[ 0 ].Position )
			return gradient.AlphaStops[ 0 ].Alpha;
		if ( t >= gradient.AlphaStops[ gradient.AlphaStops.Size - 1 ].Position )
			return gradient.AlphaStops[ gradient.AlphaStops.Size - 1 ].Alpha;

		int rightIdx = 0;
		for ( int i = 0; i < gradient.AlphaStops.Size; ++i )
		{
			if ( gradient.AlphaStops[ i ].Position >= t )
			{
				rightIdx = i;
				break;
			}
		}
		int leftIdx = rightIdx - 1;
		if ( leftIdx < 0 )
			leftIdx = 0;

		float segLen = gradient.AlphaStops[ rightIdx ].Position - gradient.AlphaStops[ leftIdx ].Position;
		float f = ( segLen > 1e-6f ) ? ( t - gradient.AlphaStops[ leftIdx ].Position ) / segLen : 0.0f;

		return ImLerp( gradient.AlphaStops[ leftIdx ].Alpha, gradient.AlphaStops[ rightIdx ].Alpha, f );
	}

	void DrawCheckerboard( ImDrawList* pDrawList, ImVec2 position, ImVec2 size, float cellSize, ImU32 col1, ImU32 col2 )
	{
		int cellsX = ( int )ImCeil( size.x / cellSize );
		int cellsY = ( int )ImCeil( size.y / cellSize );

		pDrawList->PushClipRect( position, position + size, true );
		for ( int cy = 0; cy < cellsY; ++cy )
		{
			for ( int cx = 0; cx < cellsX; ++cx )
			{
				ImU32 col = ( ( cx + cy ) % 2 == 0 ) ? col1 : col2;
				ImVec2 rMin( position.x + cx * cellSize, position.y + cy * cellSize );
				ImVec2 rMax( rMin.x + cellSize, rMin.y + cellSize );
				pDrawList->AddRectFilled( rMin, rMax, col );
			}
		}
		pDrawList->PopClipRect();
	}

	void DrawGradientBar( ImDrawList* pDrawList, ImGradientData const& gradient, ImVec2 position, ImVec2 size, int resolution )
	{
		if ( resolution < 1 )
			resolution = 1;

		ImWidgetsGradientCallbackData data;
		data.gradient = &gradient;
		DrawProceduralColor1DBilinearHorizontal( pDrawList, &ImWidgetsGradientCallback, &data,
												 0.0f, 1.0f, position, size, resolution );
	}

	void DrawSplineGradient( ImDrawList* pDrawList, ImGradientData const& gradient, const ImVec2* points, int points_count, float thickness, int resolution, bool closed )
	{
		if ( resolution < 1 )
			resolution = 1;

		ImWidgetsGradientCallbackData data;
		data.gradient = &gradient;
		DrawProceduralColorSplineBilinear( pDrawList, points, points_count, thickness,
										   &ImWidgetsGradientCallback, &data, resolution, closed );
	}

	void DrawSplineGradientCut( ImDrawList* pDrawList, ImGradientData const& gradient, float const min, float const max, const ImVec2* points, int points_count, float thickness, int resolution, bool closed )
	{
		if ( resolution < 1 )
			resolution = 1;

		ImWidgetsGradientCutCallbackData data;
		data.gradient = &gradient;
		data.min = min;
		data.max = max;
		DrawProceduralColorSplineBilinear( pDrawList, points, points_count, thickness,
										  &ImWidgetsGradientCutCallback, &data, resolution, closed );
	}

	// ========================================================================
	// Expand-to-window infrastructure
	// ========================================================================

	static bool s_InsideExpandedWidget = false;

	// Draw a small expand button at the top-right corner of a widget.
	// Returns pointer to the expanded-state bool, or NULL if inside an expanded window.
	bool* WidgetExpandButton( ImGuiID widget_id, ImRect const& bb )
	{
		if ( s_InsideExpandedWidget )
			return NULL;

		ImGuiWindow* window = ImGui::GetCurrentWindow();
		ImDrawList* dl = window->DrawList;

		ImGuiID expandKey = widget_id ^ 0x1F2E3D4C;
		bool* pOpen = window->StateStorage.GetBoolRef( expandKey, false );

		float btnSize = 32.0f;
		float margin = 3.0f;
		ImVec2 btnMin( bb.Max.x - btnSize - margin, bb.Min.y + margin );
		ImVec2 btnMax( bb.Max.x - margin, bb.Min.y + btnSize + margin );

		bool hov = ImGui::IsMouseHoveringRect( btnMin, btnMax ) && ImGui::IsWindowHovered( ImGuiHoveredFlags_AllowWhenBlockedByActiveItem );
		if ( hov && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) )
			*pOpen = !( *pOpen );

		ImU32 bg = hov ? IM_COL32( 80, 80, 80, 200 ) : IM_COL32( 40, 40, 40, 128 );
		ImU32 fg = hov ? IM_COL32_WHITE : IM_COL32( 180, 180, 180, 180 );
		dl->AddRectFilled( btnMin, btnMax, bg, 2.0f );

		// Icon: small window with title bar
		float p = 4.0f;
		ImVec2 a( btnMin.x + p, btnMin.y + p );
		ImVec2 b( btnMax.x - p, btnMax.y - p );
		dl->AddRect( a, b, fg, 0.0f, 0, 1.0f );
		dl->AddLine( ImVec2( a.x, a.y + 2.5f ), ImVec2( b.x, a.y + 2.5f ), fg, 1.0f );

		return pOpen;
	}

	// Returns true if the mouse is over the expand button area (to suppress widget interaction).
	static bool IsMouseOverExpandButton( ImGuiID widget_id, ImRect const& bb )
	{
		IM_UNUSED( widget_id );
		if ( s_InsideExpandedWidget )
			return false;

		float btnSize = 32.0f;
		float margin = 3.0f;
		ImVec2 btnMin( bb.Max.x - btnSize - margin, bb.Min.y + margin );
		ImVec2 btnMax( bb.Max.x - margin, bb.Min.y + btnSize + margin );
		return ImGui::IsMouseHoveringRect( btnMin, btnMax );
	}

	bool BeginExpandedWindow( char const* label, ImGuiID widget_id, bool* pOpen, ImVec2 defaultSize )
	{
		char title[ 256 ];
		char const* displayLabel = ( label[ 0 ] == '#' && label[ 1 ] == '#' ) ? label + 2 : label;
		ImFormatString( title, sizeof( title ), "%s###ExpandWdg_%08X", displayLabel, widget_id );
		ImGui::SetNextWindowSize( defaultSize, ImGuiCond_FirstUseEver );
		s_InsideExpandedWidget = true;
		return ImGui::Begin( title, pOpen, ImGuiWindowFlags_NoCollapse );
	}

	void EndExpandedWindow()
	{
		ImGui::End();
		s_InsideExpandedWidget = false;
	}

	bool GradientEditor( char const* label, ImGradientData* gradient, bool alpha, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );

		if ( size.x > 0.0f ) size.x = LpToPx( size.x );
		if ( size.y > 0.0f ) size.y = LpToPx( size.y );

		// We use the same id for both color and alpha tracks; selectedAlpha vs selected distinguishes them
		const float w = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float baseBarHeight = ( size.y > 0.0f ) ? size.y : ImGui::GetFrameHeight();
		const float markerHeight = LpToPx( dwStyle.Gradient_MarkerHeight );
		const float markerThickness = LpToPx( dwStyle.Gradient_MarkerThickness );
		const bool splitAlpha = gradient->SplitAlpha && alpha;
		const float barHeight = ( splitAlpha && !s_InsideExpandedWidget ) ? baseBarHeight * 5.0f : baseBarHeight;

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );

		// Layout: [alpha_marker_bb (top)] [bar_bb (middle)] [color_marker_bb (bottom)]
		// When not splitAlpha, alpha_marker_bb has zero height
		const float alphaMarkerH = splitAlpha ? markerHeight : 0.0f;
		const ImVec2 origin = window->DC.CursorPos;
		const ImRect alpha_marker_bb( origin, origin + ImVec2( w, alphaMarkerH ) );
		const ImRect bar_bb( ImVec2( origin.x, origin.y + alphaMarkerH ), ImVec2( origin.x + w, origin.y + alphaMarkerH + barHeight ) );
		const ImRect marker_bb( ImVec2( bar_bb.Min.x, bar_bb.Max.y ), ImVec2( bar_bb.Max.x, bar_bb.Max.y + markerHeight ) );
		const ImRect total_bb( origin, ImVec2( bar_bb.Max.x + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ), marker_bb.Max.y ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &bar_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( total_bb, id, g.LastItemData.ItemFlags );
		if ( IsMouseOverExpandButton( id, bar_bb ) ) hovered = false;

		bool value_changed = false;
		int& selected = gradient->SelectedIdx;
		int& selectedAlpha = gradient->SelectedAlphaIdx;

		// --- Find hovered color marker (bottom) ---
		int hovered_marker = -1;
		float closest_dist = FLT_MAX;
		for ( int i = 0; i < gradient->Stops.Size; ++i )
		{
			float x = ImLerp( bar_bb.Min.x, bar_bb.Max.x, gradient->Stops[ i ].Position );
			float dist = ImAbs( g.IO.MousePos.x - x );
			if ( dist < closest_dist && dist < markerHeight * 1.5f )
			{
				closest_dist = dist;
				hovered_marker = i;
			}
		}

		// --- Find hovered alpha marker (top) ---
		int hovered_alpha_marker = -1;
		if ( splitAlpha )
		{
			float closest_alpha_dist = FLT_MAX;
			for ( int i = 0; i < gradient->AlphaStops.Size; ++i )
			{
				float x = ImLerp( bar_bb.Min.x, bar_bb.Max.x, gradient->AlphaStops[ i ].Position );
				float dist = ImAbs( g.IO.MousePos.x - x );
				if ( dist < closest_alpha_dist && dist < markerHeight * 1.5f )
				{
					closest_alpha_dist = dist;
					hovered_alpha_marker = i;
				}
			}

			// Disambiguate: if mouse is in the top half, prefer alpha; bottom half, prefer color
			float midY = bar_bb.Min.y + barHeight * 0.5f;
			if ( hovered_marker >= 0 && hovered_alpha_marker >= 0 )
			{
				if ( g.IO.MousePos.y < midY )
					hovered_marker = -1;
				else
					hovered_alpha_marker = -1;
			}
		}

		// --- DRAWING ---
		// Frame background
		const ImU32 frame_col = ImGui::GetColorU32( ( g.ActiveId == id || g.ActiveId == id ) ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderFrame( bar_bb.Min, bar_bb.Max, frame_col, true, g.Style.FrameRounding );

		// Checkerboard for transparency (only when alpha is enabled)
		if ( alpha )
		{
			DrawCheckerboard( window->DrawList, bar_bb.Min, bar_bb.GetSize(), LpToPx( dwStyle.Gradient_CheckerboardCellSize ),
							  ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gradient_Checkerboard1 ] ),
							  ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gradient_Checkerboard2 ] ) );
		}

		// Gradient bar
		int resolution = ImMax( ( int )( w * 0.5f ), 16 );
		DrawGradientBar( window->DrawList, *gradient, bar_bb.Min, bar_bb.GetSize(), resolution );

		// Border
		window->DrawList->AddRect( bar_bb.Min, bar_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );

		// Color markers (bottom edge)
		for ( int i = 0; i < gradient->Stops.Size; ++i )
		{
			float x = ImLerp( bar_bb.Min.x, bar_bb.Max.x, gradient->Stops[ i ].Position );

			bool isSelected = ( i == selected );
			bool isHovered = ( i == hovered_marker );

			// Draw triangle marker pointing up (tip at bar bottom edge)
			ImVec2 p0( x, marker_bb.Min.y );
			ImVec2 p1( x - markerHeight * 0.5f, marker_bb.Max.y );
			ImVec2 p2( x + markerHeight * 0.5f, marker_bb.Max.y );

			// Fill with stop color (opaque preview)
			ImVec4 stopCol = gradient->Stops[ i ].Color;
			stopCol.w = 1.0f;
			window->DrawList->AddTriangleFilled( p0, p1, p2, ImGui::GetColorU32( stopCol ) );

			// Outline
			ImU32 outlineCol = ImGui::GetColorU32( dwStyle.Colors[ isSelected ? StyleColor_Gradient_MarkerOutlineSelected : ( isHovered ? StyleColor_Gradient_MarkerOutlineHovered : StyleColor_Gradient_MarkerOutline ) ] );
			float outlineThick = isSelected ? markerThickness * 2.0f : markerThickness;
			window->DrawList->AddTriangle( p0, p1, p2, outlineCol, outlineThick );

			// Alpha indicator on color markers (only when not split)
			if ( alpha && !splitAlpha && gradient->Stops[ i ].Color.w < 1.0f )
			{
				float alphaY = ImLerp( marker_bb.Min.y + 2.0f, marker_bb.Max.y - 1.0f, 1.0f - gradient->Stops[ i ].Color.w );
				float halfW = markerHeight * 0.3f;
				window->DrawList->AddLine( ImVec2( x - halfW, alphaY ), ImVec2( x + halfW, alphaY ), ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gradient_AlphaIndicator ] ), markerThickness );
			}
		}

		// Alpha markers (top edge, inverted triangles) -- only in split mode
		if ( splitAlpha )
		{
			for ( int i = 0; i < gradient->AlphaStops.Size; ++i )
			{
				float x = ImLerp( bar_bb.Min.x, bar_bb.Max.x, gradient->AlphaStops[ i ].Position );

				bool isSelected = ( i == selectedAlpha );
				bool isHovered = ( i == hovered_alpha_marker );

				// Draw inverted triangle marker: tip points down (at bar top edge), base at top
				ImVec2 p0( x, alpha_marker_bb.Max.y );                              // tip (bottom)
				ImVec2 p1( x + markerHeight * 0.5f, alpha_marker_bb.Min.y );        // base right (top)
				ImVec2 p2( x - markerHeight * 0.5f, alpha_marker_bb.Min.y );        // base left (top)

				// Fill: white-to-black proportional to alpha
				float a = gradient->AlphaStops[ i ].Alpha;
				ImU32 fillCol = IM_COL32( (int)( a * 255 ), (int)( a * 255 ), (int)( a * 255 ), 255 );
				window->DrawList->AddTriangleFilled( p0, p1, p2, fillCol );

				// Outline
				ImU32 outlineCol = ImGui::GetColorU32( dwStyle.Colors[ isSelected ? StyleColor_Gradient_MarkerOutlineSelected : ( isHovered ? StyleColor_Gradient_MarkerOutlineHovered : StyleColor_Gradient_MarkerOutline ) ] );
				float outlineThick = isSelected ? markerThickness * 2.0f : markerThickness;
				window->DrawList->AddTriangle( p0, p1, p2, outlineCol, outlineThick );
			}
		}

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( bar_bb.Max.x + style.ItemInnerSpacing.x, bar_bb.Min.y + style.FramePadding.y ), label );

		// --- INTERACTIONS ---
		ImGui::PushID( id );

		bool bar_contains_mouse = bar_bb.Contains( g.IO.MousePos );

		// ========================
		// Color stop interactions
		// ========================

		bool mouseInColorZone = !splitAlpha || g.IO.MousePos.y >= bar_bb.Min.y;

		// Double-click on color marker: open color picker
		if ( hovered_marker >= 0 && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) && hovered && mouseInColorZone )
		{
			selected = hovered_marker;
			selectedAlpha = -1;
			ImGui::OpenPopup( "##GradStopPicker" );
		}
		// Click on color marker: select and start drag
		else if ( hovered_marker >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && mouseInColorZone )
		{
			selected = hovered_marker;
			selectedAlpha = -1;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}
		// Click on empty bar: in split mode, top half adds alpha key, bottom half adds color key
		// In non-split mode, always adds color key
		else if ( bar_contains_mouse && hovered_marker == -1 && hovered_alpha_marker == -1
				  && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered )
		{
			float t = ImClamp( ( g.IO.MousePos.x - bar_bb.Min.x ) / bar_bb.GetWidth(), 0.0f, 1.0f );
			bool mouseInTopHalf = splitAlpha && g.IO.MousePos.y < bar_bb.Min.y + barHeight * 0.5f;
			if ( mouseInTopHalf )
			{
				// Top half in split mode: add alpha key only
				float a = GradientAlphaSample( *gradient, t );
				int newIdx = gradient->AddAlphaStop( t, a );
				selectedAlpha = newIdx;
				selected = -1;
				value_changed = true;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}
			else
			{
				// Bottom half (or non-split): add color key only
				ImVec4 col = GradientSample( *gradient, t );
				if ( splitAlpha ) col.w = 1.0f;
				int newIdx = gradient->AddStop( t, col );
				selected = newIdx;
				selectedAlpha = -1;
				value_changed = true;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}
		}

		// Drag color stop
		if ( g.ActiveId == id && selected >= 0 && selected < gradient->Stops.Size && ImGui::IsMouseDragging( ImGuiMouseButton_Left ) )
		{
			float t = ImClamp( ( g.IO.MousePos.x - bar_bb.Min.x ) / bar_bb.GetWidth(), 0.0f, 1.0f );
			ImVec4 draggedColor = gradient->Stops[ selected ].Color;
			gradient->Stops[ selected ].Position = t;
			gradient->SortStops();
			for ( int i = 0; i < gradient->Stops.Size; ++i )
			{
				if ( gradient->Stops[ i ].Position == t && gradient->Stops[ i ].Color.x == draggedColor.x
					 && gradient->Stops[ i ].Color.y == draggedColor.y && gradient->Stops[ i ].Color.z == draggedColor.z
					 && gradient->Stops[ i ].Color.w == draggedColor.w )
				{
					selected = i;
					break;
				}
			}
			value_changed = true;

			// Drag far below the marker area: delete the stop
			if ( g.IO.MousePos.y > marker_bb.Max.y + markerHeight * 3.0f && gradient->Stops.Size > 2 )
			{
				gradient->RemoveStop( selected );
				selected = -1;
				ImGui::ClearActiveID();
				value_changed = true;
			}
		}

		// Release color drag
		if ( g.ActiveId == id && ImGui::IsMouseReleased( ImGuiMouseButton_Left ) )
		{
			ImGui::ClearActiveID();
		}

		// Right-click context menu for color stops
		if ( hovered_marker >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Right ) && hovered )
		{
			selected = hovered_marker;
			selectedAlpha = -1;
			ImGui::OpenPopup( "##GradStopCtx" );
		}

		// ========================
		// Alpha stop interactions (split mode only)
		// ========================

		if ( splitAlpha )
		{
			bool mouseInAlphaZone = g.IO.MousePos.y < bar_bb.Min.y + barHeight * 0.5f;

			// Double-click on alpha marker: open alpha editor
			if ( hovered_alpha_marker >= 0 && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) && hovered && mouseInAlphaZone )
			{
				selectedAlpha = hovered_alpha_marker;
				selected = -1;
				ImGui::OpenPopup( "##GradAlphaPicker" );
			}
			// Click on alpha marker: select and start drag
			else if ( hovered_alpha_marker >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && mouseInAlphaZone )
			{
				selectedAlpha = hovered_alpha_marker;
				selected = -1;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}

			// Drag alpha stop
			if ( g.ActiveId == id && selectedAlpha >= 0 && selectedAlpha < gradient->AlphaStops.Size && ImGui::IsMouseDragging( ImGuiMouseButton_Left ) )
			{
				float t = ImClamp( ( g.IO.MousePos.x - bar_bb.Min.x ) / bar_bb.GetWidth(), 0.0f, 1.0f );
				float draggedAlpha = gradient->AlphaStops[ selectedAlpha ].Alpha;
				gradient->AlphaStops[ selectedAlpha ].Position = t;
				gradient->SortAlphaStops();
				for ( int i = 0; i < gradient->AlphaStops.Size; ++i )
				{
					if ( gradient->AlphaStops[ i ].Position == t && gradient->AlphaStops[ i ].Alpha == draggedAlpha )
					{
						selectedAlpha = i;
						break;
					}
				}
				value_changed = true;

				// Drag far above the alpha marker area: delete
				if ( g.IO.MousePos.y < alpha_marker_bb.Min.y - markerHeight * 3.0f && gradient->AlphaStops.Size > 2 )
				{
					gradient->RemoveAlphaStop( selectedAlpha );
					selectedAlpha = -1;
					ImGui::ClearActiveID();
					value_changed = true;
				}
			}

			// Right-click context menu for alpha stops
			if ( hovered_alpha_marker >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Right ) && hovered )
			{
				selectedAlpha = hovered_alpha_marker;
				selected = -1;
				ImGui::OpenPopup( "##GradAlphaCtx" );
			}
		}

		// Color picker popup
		if ( ImGui::BeginPopup( "##GradStopPicker" ) )
		{
			if ( selected >= 0 && selected < gradient->Stops.Size )
			{
				ImGuiColorEditFlags pickerFlags = ( alpha && !splitAlpha ) ? ( ImGuiColorEditFlags_AlphaBar | ImGuiColorEditFlags_AlphaPreviewHalf ) : ImGuiColorEditFlags_NoAlpha;
				if ( ImGui::ColorPicker4( "##picker", &gradient->Stops[ selected ].Color.x, pickerFlags ) )
				{
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}

		// Alpha editor popup (split mode)
		if ( ImGui::BeginPopup( "##GradAlphaPicker" ) )
		{
			if ( selectedAlpha >= 0 && selectedAlpha < gradient->AlphaStops.Size )
			{
				ImGui::Text( "Alpha Stop %d", selectedAlpha );
				ImGui::SetNextItemWidth( 200.0f );
				if ( ImGui::SliderFloat( "##alpha", &gradient->AlphaStops[ selectedAlpha ].Alpha, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::SetNextItemWidth( 200.0f );
				if ( ImGui::SliderFloat( "##pos", &gradient->AlphaStops[ selectedAlpha ].Position, 0.0f, 1.0f, "pos: %.3f" ) )
				{
					gradient->SortAlphaStops();
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}

		// Context menu popup (color stops)
		bool openPickerDeferred = false;
		if ( ImGui::BeginPopup( "##GradStopCtx" ) )
		{
			if ( ImGui::MenuItem( "Edit Color" ) )
			{
				openPickerDeferred = true;
			}
			if ( ImGui::MenuItem( "Remove Stop", NULL, false, gradient->Stops.Size > 2 ) )
			{
				if ( gradient->RemoveStop( selected ) )
				{
					selected = -1;
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}
		if ( openPickerDeferred )
			ImGui::OpenPopup( "##GradStopPicker" );

		// Context menu popup (alpha stops)
		bool openAlphaPickerDeferred = false;
		if ( ImGui::BeginPopup( "##GradAlphaCtx" ) )
		{
			if ( ImGui::MenuItem( "Edit Alpha" ) )
			{
				openAlphaPickerDeferred = true;
			}
			if ( ImGui::MenuItem( "Remove Alpha Stop", NULL, false, gradient->AlphaStops.Size > 2 ) )
			{
				if ( gradient->RemoveAlphaStop( selectedAlpha ) )
				{
					selectedAlpha = -1;
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}
		if ( openAlphaPickerDeferred )
			ImGui::OpenPopup( "##GradAlphaPicker" );

		// Delete key -- works on whichever track is active
		if ( ImGui::IsKeyPressed( ImGuiKey_Delete ) && hovered )
		{
			if ( selected >= 0 )
			{
				if ( gradient->RemoveStop( selected ) )
				{
					selected = -1;
					value_changed = true;
				}
			}
			else if ( selectedAlpha >= 0 )
			{
				if ( gradient->RemoveAlphaStop( selectedAlpha ) )
				{
					selectedAlpha = -1;
					value_changed = true;
				}
			}
		}

		// Arrow key nudging -- color track
		if ( selected >= 0 && selected < gradient->Stops.Size && hovered )
		{
			ImGui::SetKeyOwner( ImGuiKey_LeftArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_RightArrow, id );
			float step = 1.0f / ImMax( bar_bb.GetWidth(), 1.0f );
			if ( ImGui::GetIO().KeyShift )
				step *= 10.0f;
			if ( ImGui::IsKeyPressed( ImGuiKey_LeftArrow ) )
			{
				gradient->Stops[ selected ].Position = ImClamp( gradient->Stops[ selected ].Position - step, 0.0f, 1.0f );
				gradient->SortStops();
				value_changed = true;
			}
			if ( ImGui::IsKeyPressed( ImGuiKey_RightArrow ) )
			{
				gradient->Stops[ selected ].Position = ImClamp( gradient->Stops[ selected ].Position + step, 0.0f, 1.0f );
				gradient->SortStops();
				value_changed = true;
			}
		}

		// Arrow key nudging -- alpha track
		if ( splitAlpha && selectedAlpha >= 0 && selectedAlpha < gradient->AlphaStops.Size && hovered )
		{
			ImGui::SetKeyOwner( ImGuiKey_LeftArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_RightArrow, id );
			float step = 1.0f / ImMax( bar_bb.GetWidth(), 1.0f );
			if ( ImGui::GetIO().KeyShift )
				step *= 10.0f;
			if ( ImGui::IsKeyPressed( ImGuiKey_LeftArrow ) )
			{
				gradient->AlphaStops[ selectedAlpha ].Position = ImClamp( gradient->AlphaStops[ selectedAlpha ].Position - step, 0.0f, 1.0f );
				gradient->SortAlphaStops();
				value_changed = true;
			}
			if ( ImGui::IsKeyPressed( ImGuiKey_RightArrow ) )
			{
				gradient->AlphaStops[ selectedAlpha ].Position = ImClamp( gradient->AlphaStops[ selectedAlpha ].Position + step, 0.0f, 1.0f );
				gradient->SortAlphaStops();
				value_changed = true;
			}
		}

		// Tooltip
		if ( hovered_marker >= 0 && hovered_marker < gradient->Stops.Size && hovered && g.ActiveId != id )
		{
			if ( splitAlpha )
				ImGui::SetTooltip( "Color %d: pos=%.3f RGB=(%.2f, %.2f, %.2f)",
					hovered_marker, gradient->Stops[ hovered_marker ].Position,
					gradient->Stops[ hovered_marker ].Color.x, gradient->Stops[ hovered_marker ].Color.y,
					gradient->Stops[ hovered_marker ].Color.z );
			else
				ImGui::SetTooltip( "Stop %d: pos=%.3f RGBA=(%.2f, %.2f, %.2f, %.2f)",
					hovered_marker, gradient->Stops[ hovered_marker ].Position,
					gradient->Stops[ hovered_marker ].Color.x, gradient->Stops[ hovered_marker ].Color.y,
					gradient->Stops[ hovered_marker ].Color.z, gradient->Stops[ hovered_marker ].Color.w );
		}
		if ( splitAlpha && hovered_alpha_marker >= 0 && hovered_alpha_marker < gradient->AlphaStops.Size && hovered && g.ActiveId != id )
		{
			ImGui::SetTooltip( "Alpha %d: pos=%.3f alpha=%.3f",
				hovered_alpha_marker, gradient->AlphaStops[ hovered_alpha_marker ].Position,
				gradient->AlphaStops[ hovered_alpha_marker ].Alpha );
		}

		ImGui::PopID();

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, bar_bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: widget
				if ( GradientEditor( "##exp", gradient, alpha, ImVec2( widgetW, avail.y * 0.5f ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info / edit
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				if ( alpha )
				{
					if ( ImGui::Checkbox( "Split Alpha", &gradient->SplitAlpha ) )
						value_changed = true;
				}
				ImGui::TextUnformatted( "Stops" );
				ImGui::Text( "Color: %d  Alpha: %d", gradient->Stops.Size, gradient->AlphaStops.Size );
				ImGui::Spacing();
				ImGui::TextUnformatted( "Interpolation" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::Combo( "##interp", ( int* )&gradient->Interpolation, "sRGB\0Linear sRGB\0OkLab\0OkLCH\0HSV\0" ) )
					value_changed = true;
				if ( selected >= 0 && selected < gradient->Stops.Size )
				{
					ImGui::Separator();
					ImGui::TextUnformatted( "Selected Color Stop" );
					ImGui::Text( "%d", selected );
					ImGui::Spacing();
					ImGui::TextUnformatted( "Position" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##pos", &gradient->Stops[ selected ].Position, 0.001f, 0.0f, 1.0f, "%.3f" ) )
					{
						gradient->SortStops();
						value_changed = true;
					}
					if ( selected >= 0 && selected < gradient->Stops.Size )
					{
						ImVec4& stopColor = gradient->Stops[ selected ].Color;
						ImGui::Spacing();
						ImGui::TextUnformatted( "Color" );
						ImGui::SetNextItemWidth( -FLT_MIN );
						if ( ImGui::DragFloat( "##r", &stopColor.x, 0.001f, 0.0f, 1.0f, "R: %.3f" ) )
							value_changed = true;
						ImGui::SetNextItemWidth( -FLT_MIN );
						if ( ImGui::DragFloat( "##g", &stopColor.y, 0.001f, 0.0f, 1.0f, "G: %.3f" ) )
							value_changed = true;
						ImGui::SetNextItemWidth( -FLT_MIN );
						if ( ImGui::DragFloat( "##b", &stopColor.z, 0.001f, 0.0f, 1.0f, "B: %.3f" ) )
							value_changed = true;
						if ( alpha && !splitAlpha )
						{
							ImGui::SetNextItemWidth( -FLT_MIN );
							if ( ImGui::DragFloat( "##a", &stopColor.w, 0.001f, 0.0f, 1.0f, "A: %.3f" ) )
								value_changed = true;
						}
						ImGui::Spacing();
						ImVec4 preview = stopColor; preview.w = 1.0f;
						ImGui::ColorButton( "##preview", preview, 0, ImVec2( ImGui::GetContentRegionAvail().x, 20 ) );
					}
				}
				if ( splitAlpha && selectedAlpha >= 0 && selectedAlpha < gradient->AlphaStops.Size )
				{
					ImGui::Separator();
					ImGui::TextUnformatted( "Selected Alpha Stop" );
					ImGui::Text( "%d", selectedAlpha );
					ImGui::Spacing();
					ImGui::TextUnformatted( "Position" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##apos", &gradient->AlphaStops[ selectedAlpha ].Position, 0.001f, 0.0f, 1.0f, "%.3f" ) )
					{
						gradient->SortAlphaStops();
						value_changed = true;
					}
					ImGui::Spacing();
					ImGui::TextUnformatted( "Alpha" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##aval", &gradient->AlphaStops[ selectedAlpha ].Alpha, 0.001f, 0.0f, 1.0f, "%.3f" ) )
						value_changed = true;
				}
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		if ( value_changed && ( g.ActiveId == id || g.ActiveId == 0 ) )
			ImGui::MarkItemEdited( id );

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Curve Editor - Easing Functions
	//////////////////////////////////////////////////////////////////////////

	static float ImEaseOutBounce( float t )
	{
		if ( t < 1.0f / 2.75f )
			return 7.5625f * t * t;
		if ( t < 2.0f / 2.75f )
		{
			t -= 1.5f / 2.75f;
			return 7.5625f * t * t + 0.75f;
		}
		if ( t < 2.5f / 2.75f )
		{
			t -= 2.25f / 2.75f;
			return 7.5625f * t * t + 0.9375f;
		}
		t -= 2.625f / 2.75f;
		return 7.5625f * t * t + 0.984375f;
	}

	float CurveEditorEvalEasing( ImCurveEditorSeg seg, float t )
	{
		t = ImClamp( t, 0.0f, 1.0f );
		float u;
		switch ( seg )
		{
		// Linear
		case ImCurveEditorSeg_Linear:
			return t;

		// Quad
		case ImCurveEditorSeg_InQuad:
			return t * t;
		case ImCurveEditorSeg_OutQuad:
			return t * ( 2.0f - t );
		case ImCurveEditorSeg_InOutQuad:
			return t < 0.5f ? 2.0f * t * t : -1.0f + ( 4.0f - 2.0f * t ) * t;

		// Cubic
		case ImCurveEditorSeg_InCubic:
			return t * t * t;
		case ImCurveEditorSeg_OutCubic:
			u = t - 1.0f;
			return u * u * u + 1.0f;
		case ImCurveEditorSeg_InOutCubic:
			return t < 0.5f ? 4.0f * t * t * t : ( t - 1.0f ) * ( 2.0f * t - 2.0f ) * ( 2.0f * t - 2.0f ) + 1.0f;

		// Quart
		case ImCurveEditorSeg_InQuart:
			return t * t * t * t;
		case ImCurveEditorSeg_OutQuart:
			u = t - 1.0f;
			return 1.0f - u * u * u * u;
		case ImCurveEditorSeg_InOutQuart:
			u = t - 1.0f;
			return t < 0.5f ? 8.0f * t * t * t * t : 1.0f - 8.0f * u * u * u * u;

		// Quint
		case ImCurveEditorSeg_InQuint:
			return t * t * t * t * t;
		case ImCurveEditorSeg_OutQuint:
			u = t - 1.0f;
			return 1.0f + u * u * u * u * u;
		case ImCurveEditorSeg_InOutQuint:
			u = t - 1.0f;
			return t < 0.5f ? 16.0f * t * t * t * t * t : 1.0f + 16.0f * u * u * u * u * u;

		// Sine
		case ImCurveEditorSeg_InSine:
			return 1.0f - ImCos( t * IM_PI * 0.5f );
		case ImCurveEditorSeg_OutSine:
			return ImSin( t * IM_PI * 0.5f );
		case ImCurveEditorSeg_InOutSine:
			return 0.5f * ( 1.0f - ImCos( IM_PI * t ) );

		// Expo
		case ImCurveEditorSeg_InExpo:
			return t == 0.0f ? 0.0f : ImPow( 2.0f, 10.0f * ( t - 1.0f ) );
		case ImCurveEditorSeg_OutExpo:
			return t == 1.0f ? 1.0f : 1.0f - ImPow( 2.0f, -10.0f * t );
		case ImCurveEditorSeg_InOutExpo:
			if ( t == 0.0f ) return 0.0f;
			if ( t == 1.0f ) return 1.0f;
			return t < 0.5f ? 0.5f * ImPow( 2.0f, 20.0f * t - 10.0f ) : 1.0f - 0.5f * ImPow( 2.0f, -20.0f * t + 10.0f );

		// Circ
		case ImCurveEditorSeg_InCirc:
			return 1.0f - ImSqrt( 1.0f - t * t );
		case ImCurveEditorSeg_OutCirc:
			u = t - 1.0f;
			return ImSqrt( 1.0f - u * u );
		case ImCurveEditorSeg_InOutCirc:
			u = 2.0f * t - 2.0f;
			return t < 0.5f ? 0.5f * ( 1.0f - ImSqrt( 1.0f - 4.0f * t * t ) ) : 0.5f * ( ImSqrt( 1.0f - u * u ) + 1.0f );

		// Back
		case ImCurveEditorSeg_InBack:
		{
			const float s = 1.70158f;
			return t * t * ( ( s + 1.0f ) * t - s );
		}
		case ImCurveEditorSeg_OutBack:
		{
			const float s = 1.70158f;
			u = t - 1.0f;
			return u * u * ( ( s + 1.0f ) * u + s ) + 1.0f;
		}
		case ImCurveEditorSeg_InOutBack:
		{
			const float s = 1.70158f * 1.525f;
			u = t * 2.0f;
			if ( u < 1.0f ) return 0.5f * u * u * ( ( s + 1.0f ) * u - s );
			u -= 2.0f;
			return 0.5f * ( u * u * ( ( s + 1.0f ) * u + s ) + 2.0f );
		}

		// Elastic
		case ImCurveEditorSeg_InElastic:
			if ( t == 0.0f || t == 1.0f ) return t;
			return -ImPow( 2.0f, 10.0f * ( t - 1.0f ) ) * ImSin( ( t - 1.1f ) * 5.0f * IM_PI );
		case ImCurveEditorSeg_OutElastic:
			if ( t == 0.0f || t == 1.0f ) return t;
			return ImPow( 2.0f, -10.0f * t ) * ImSin( ( t - 0.1f ) * 5.0f * IM_PI ) + 1.0f;
		case ImCurveEditorSeg_InOutElastic:
			if ( t == 0.0f || t == 1.0f ) return t;
			u = t * 2.0f;
			if ( u < 1.0f ) return -0.5f * ImPow( 2.0f, 10.0f * ( u - 1.0f ) ) * ImSin( ( u - 1.1f ) * 5.0f * IM_PI );
			return 0.5f * ImPow( 2.0f, -10.0f * ( u - 1.0f ) ) * ImSin( ( u - 1.1f ) * 5.0f * IM_PI ) + 1.0f;

		// Bounce
		case ImCurveEditorSeg_InBounce:
			return 1.0f - ImEaseOutBounce( 1.0f - t );
		case ImCurveEditorSeg_OutBounce:
			return ImEaseOutBounce( t );
		case ImCurveEditorSeg_InOutBounce:
			return t < 0.5f ? 0.5f * ( 1.0f - ImEaseOutBounce( 1.0f - 2.0f * t ) ) : 0.5f * ImEaseOutBounce( 2.0f * t - 1.0f ) + 0.5f;

		default:
			return t;
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// Curve Editor - Sampling
	//////////////////////////////////////////////////////////////////////////

	static float ImBezierCubicEval1D( float p0, float p1, float p2, float p3, float t )
	{
		float u = 1.0f - t;
		return u * u * u * p0 + 3.0f * u * u * t * p1 + 3.0f * u * t * t * p2 + t * t * t * p3;
	}

	static float ImBezierSolveForX( float p0x, float p1x, float p2x, float p3x, float targetX )
	{
		float lo = 0.0f, hi = 1.0f;
		for ( int i = 0; i < 24; ++i )
		{
			float mid = ( lo + hi ) * 0.5f;
			float x = ImBezierCubicEval1D( p0x, p1x, p2x, p3x, mid );
			if ( x < targetX )
				lo = mid;
			else
				hi = mid;
		}
		return ( lo + hi ) * 0.5f;
	}

	float CurveEditorSample( ImCurveEditorData const& curve, float x )
	{
		if ( curve.Keys.Size == 0 )
			return 0.0f;
		if ( curve.Keys.Size == 1 )
			return curve.Keys[ 0 ].Pos.y;

		// Clamp to key range
		if ( x <= curve.Keys[ 0 ].Pos.x )
			return curve.Keys[ 0 ].Pos.y;
		if ( x >= curve.Keys[ curve.Keys.Size - 1 ].Pos.x )
			return curve.Keys[ curve.Keys.Size - 1 ].Pos.y;

		// Find segment
		int rightIdx = 0;
		for ( int i = 0; i < curve.Keys.Size; ++i )
		{
			if ( curve.Keys[ i ].Pos.x >= x )
			{
				rightIdx = i;
				break;
			}
		}
		int leftIdx = rightIdx - 1;
		if ( leftIdx < 0 )
			leftIdx = 0;

		ImCurveEditorKey const& k0 = curve.Keys[ leftIdx ];
		ImCurveEditorKey const& k1 = curve.Keys[ rightIdx ];

		float dx = k1.Pos.x - k0.Pos.x;
		float t = ( dx > 1e-6f ) ? ( x - k0.Pos.x ) / dx : 0.0f;

		ImCurveEditorSeg seg = k0.Segment;

		// Step modes
		if ( seg == ImCurveEditorSeg_StepStart )
			return k0.Pos.y;
		if ( seg == ImCurveEditorSeg_StepEnd )
			return k1.Pos.y;
		if ( seg == ImCurveEditorSeg_StepCenter )
			return t < 0.5f ? k0.Pos.y : k1.Pos.y;

		// Cubic Bezier with tangent handles
		if ( seg == ImCurveEditorSeg_CubicBezier )
		{
			ImVec2 p0 = k0.Pos;
			ImVec2 p1 = k0.Pos + k0.TangentRight;
			ImVec2 p2 = k1.Pos + k1.TangentLeft;
			ImVec2 p3 = k1.Pos;

			float bt = ImBezierSolveForX( p0.x, p1.x, p2.x, p3.x, x );
			return ImBezierCubicEval1D( p0.y, p1.y, p2.y, p3.y, bt );
		}

		// Easing: apply easing to t, then lerp y
		float easedT = CurveEditorEvalEasing( seg, t );
		return ImLerp( k0.Pos.y, k1.Pos.y, easedT );
	}

	//////////////////////////////////////////////////////////////////////////
	// Curve Editor - Widget
	//////////////////////////////////////////////////////////////////////////

	const char* CurveEditorSegName( ImCurveEditorSeg seg )
	{
		switch ( seg )
		{
		case ImCurveEditorSeg_StepStart:     return "Step Start";
		case ImCurveEditorSeg_StepEnd:       return "Step End";
		case ImCurveEditorSeg_StepCenter:    return "Step Center";
		case ImCurveEditorSeg_Linear:        return "Linear";
		case ImCurveEditorSeg_InQuad:        return "In Quad";
		case ImCurveEditorSeg_OutQuad:       return "Out Quad";
		case ImCurveEditorSeg_InOutQuad:     return "InOut Quad";
		case ImCurveEditorSeg_InCubic:       return "In Cubic";
		case ImCurveEditorSeg_OutCubic:      return "Out Cubic";
		case ImCurveEditorSeg_InOutCubic:    return "InOut Cubic";
		case ImCurveEditorSeg_InQuart:       return "In Quart";
		case ImCurveEditorSeg_OutQuart:      return "Out Quart";
		case ImCurveEditorSeg_InOutQuart:    return "InOut Quart";
		case ImCurveEditorSeg_InQuint:       return "In Quint";
		case ImCurveEditorSeg_OutQuint:      return "Out Quint";
		case ImCurveEditorSeg_InOutQuint:    return "InOut Quint";
		case ImCurveEditorSeg_InSine:        return "In Sine";
		case ImCurveEditorSeg_OutSine:       return "Out Sine";
		case ImCurveEditorSeg_InOutSine:     return "InOut Sine";
		case ImCurveEditorSeg_InExpo:        return "In Expo";
		case ImCurveEditorSeg_OutExpo:       return "Out Expo";
		case ImCurveEditorSeg_InOutExpo:     return "InOut Expo";
		case ImCurveEditorSeg_InCirc:        return "In Circ";
		case ImCurveEditorSeg_OutCirc:       return "Out Circ";
		case ImCurveEditorSeg_InOutCirc:     return "InOut Circ";
		case ImCurveEditorSeg_InBack:        return "In Back";
		case ImCurveEditorSeg_OutBack:       return "Out Back";
		case ImCurveEditorSeg_InOutBack:     return "InOut Back";
		case ImCurveEditorSeg_InElastic:     return "In Elastic";
		case ImCurveEditorSeg_OutElastic:    return "Out Elastic";
		case ImCurveEditorSeg_InOutElastic:  return "InOut Elastic";
		case ImCurveEditorSeg_InBounce:      return "In Bounce";
		case ImCurveEditorSeg_OutBounce:     return "Out Bounce";
		case ImCurveEditorSeg_InOutBounce:   return "InOut Bounce";
		case ImCurveEditorSeg_CubicBezier:   return "Cubic Bezier";
		default:                             return "Unknown";
		}
	}

	const char* CurveEditorTangentModeName( ImCurveEditorTangentMode mode )
	{
		switch ( mode )
		{
		case ImCurveEditorTangentMode_Free:     return "Free";
		case ImCurveEditorTangentMode_Aligned:  return "Aligned";
		case ImCurveEditorTangentMode_Mirrored: return "Mirrored";
		default:                                return "Unknown";
		}
	}

	static ImVec2 CurveToScreen( ImVec2 curvePos, ImRect const& bb, ImVec2 rangeMin, ImVec2 rangeMax )
	{
		float sx = ( curvePos.x - rangeMin.x ) / ( rangeMax.x - rangeMin.x );
		float sy = 1.0f - ( curvePos.y - rangeMin.y ) / ( rangeMax.y - rangeMin.y ); // Y flipped
		return ImVec2( ImLerp( bb.Min.x, bb.Max.x, sx ), ImLerp( bb.Min.y, bb.Max.y, sy ) );
	}

	static ImVec2 ScreenToCurve( ImVec2 screenPos, ImRect const& bb, ImVec2 rangeMin, ImVec2 rangeMax )
	{
		float sx = ( screenPos.x - bb.Min.x ) / ( bb.Max.x - bb.Min.x );
		float sy = 1.0f - ( screenPos.y - bb.Min.y ) / ( bb.Max.y - bb.Min.y ); // Y flipped
		return ImVec2( ImLerp( rangeMin.x, rangeMax.x, sx ), ImLerp( rangeMin.y, rangeMax.y, sy ) );
	}

	static ImVec2 ScreenVecToCurve( ImVec2 screenVec, ImRect const& bb, ImVec2 rangeMin, ImVec2 rangeMax )
	{
		float scaleX = ( rangeMax.x - rangeMin.x ) / bb.GetWidth();
		float scaleY = -( rangeMax.y - rangeMin.y ) / bb.GetHeight(); // Y flipped
		return ImVec2( screenVec.x * scaleX, screenVec.y * scaleY );
	}

	// ========================================================================
	// Shared Bezier Tangent Helpers
	// ========================================================================

	// Enforce tangent mode constraint after one handle changes.
	// 'side' indicates which handle was modified: -1 = left, +1 = right.
	static void EnforceTangentMode( ImVec2& tangentLeft, ImVec2& tangentRight, ImCurveEditorTangentMode mode, int side )
	{
		if ( mode == ImCurveEditorTangentMode_Mirrored )
		{
			if ( side == -1 )
			{
				tangentRight = ImVec2( -tangentLeft.x, -tangentLeft.y );
				if ( tangentRight.x < 0.0f ) tangentRight.x = 0.0f;
			}
			else
			{
				tangentLeft = ImVec2( -tangentRight.x, -tangentRight.y );
				if ( tangentLeft.x > 0.0f ) tangentLeft.x = 0.0f;
			}
		}
		else if ( mode == ImCurveEditorTangentMode_Aligned )
		{
			float lenL = ImSqrt( ImLengthSqr( tangentLeft ) );
			float lenR = ImSqrt( ImLengthSqr( tangentRight ) );
			if ( side == -1 && lenL > 1e-6f )
			{
				tangentRight = ImVec2( -tangentLeft.x, -tangentLeft.y ) * ( lenR / lenL );
				if ( tangentRight.x < 0.0f ) tangentRight.x = 0.0f;
			}
			else if ( side == 1 && lenR > 1e-6f )
			{
				tangentLeft = ImVec2( -tangentRight.x, -tangentRight.y ) * ( lenL / lenR );
				if ( tangentLeft.x > 0.0f ) tangentLeft.x = 0.0f;
			}
		}
	}

	// Hit-test bezier tangent handles for a selected key.
	// keyScreen: key position in screen coords.
	// tanLeftScreen, tanRightScreen: tangent endpoint in screen coords.
	// showLeft, showRight: whether each handle exists.
	// Returns -1 (left), +1 (right), or 0 (none).
	static int HitTestBezierHandles( ImVec2 mousePos, ImVec2 tanLeftScreen, ImVec2 tanRightScreen,
									  bool showLeft, bool showRight, float hitRadiusSq )
	{
		int result = 0;
		float bestSq = hitRadiusSq;
		if ( showLeft )
		{
			float dSq = ImLengthSqr( mousePos - tanLeftScreen );
			if ( dSq < bestSq ) { bestSq = dSq; result = -1; }
		}
		if ( showRight )
		{
			float dSq = ImLengthSqr( mousePos - tanRightScreen );
			if ( dSq < bestSq ) { bestSq = dSq; result = 1; }
		}
		return result;
	}

	// Draw bezier tangent handles (lines + circles) for a selected key.
	static void DrawBezierHandles( ImDrawList* dl, ImVec2 keyScreen,
									ImVec2 tanLeftScreen, ImVec2 tanRightScreen,
									bool showLeft, bool showRight,
									int hoveredTangent,
									ImU32 tangentCol, ImU32 tangentHovCol,
									float lineThick, float handleRadius )
	{
		if ( showLeft )
		{
			bool hov = ( hoveredTangent == -1 );
			dl->AddLine( keyScreen, tanLeftScreen, hov ? tangentHovCol : tangentCol, hov ? lineThick : lineThick * 0.5f );
			dl->AddCircleFilled( tanLeftScreen, hov ? handleRadius + LpToPx( 1.5f ) : handleRadius, hov ? tangentHovCol : tangentCol );
		}
		if ( showRight )
		{
			bool hov = ( hoveredTangent == 1 );
			dl->AddLine( keyScreen, tanRightScreen, hov ? tangentHovCol : tangentCol, hov ? lineThick : lineThick * 0.5f );
			dl->AddCircleFilled( tanRightScreen, hov ? handleRadius + LpToPx( 1.5f ) : handleRadius, hov ? tangentHovCol : tangentCol );
		}
	}

	// UI helper: draw tangent mode + handle editing controls in expanded window panels.
	// Returns true if value_changed.
	static bool TangentModeUI( ImVec2& tangentLeft, ImVec2& tangentRight, ImCurveEditorTangentMode& tangentMode )
	{
		bool changed = false;
		ImGui::Spacing();
		ImGui::TextUnformatted( "Tangent" );
		ImGui::SetNextItemWidth( -FLT_MIN );
		int tm = ( int )tangentMode;
		if ( ImGui::Combo( "##tangent", &tm, "Free\0Aligned\0Mirrored\0" ) )
		{
			tangentMode = ( ImCurveEditorTangentMode )tm;
			EnforceTangentMode( tangentLeft, tangentRight, tangentMode, -1 );
			changed = true;
		}
		ImGui::Spacing();
		ImGui::TextUnformatted( "Left Tangent" );
		ImGui::SetNextItemWidth( -FLT_MIN );
		if ( ImGui::DragFloat2( "##tanL", &tangentLeft.x, 0.001f, 0.0f, 0.0f, "%.3f" ) )
		{
			if ( tangentLeft.x > 0.0f ) tangentLeft.x = 0.0f;
			EnforceTangentMode( tangentLeft, tangentRight, tangentMode, -1 );
			changed = true;
		}
		ImGui::TextUnformatted( "Right Tangent" );
		ImGui::SetNextItemWidth( -FLT_MIN );
		if ( ImGui::DragFloat2( "##tanR", &tangentRight.x, 0.001f, 0.0f, 0.0f, "%.3f" ) )
		{
			if ( tangentRight.x < 0.0f ) tangentRight.x = 0.0f;
			EnforceTangentMode( tangentLeft, tangentRight, tangentMode, 1 );
			changed = true;
		}
		return changed;
	}

