		const float dotOutlineThick = LpToPx( dwStyle.ColorPicker_DotOutlineThickness );

		ImGui::InvisibleButton( "plane", ImVec2( planeSide, planeSide ) );
		const ImRect plane_bb( ImGui::GetItemRectMin(), ImGui::GetItemRectMax() );
