		if ( !fp ) return;
		fprintf( fp, "# DearWidgets style export\n" );
#define DW_SF(f) fprintf( fp, #f "=%.6g\n", s.f )
#define DW_SI(f) fprintf( fp, #f "=%d\n",   (int)s.f )
#define DW_SB(f) fprintf( fp, #f "=%d\n",   s.f ? 1 : 0 )
		DW_SF( HueSelector_Thickness_ZeroWidth );
